insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tornado','A tornado warning is issued for our area during your shift. Where do guests and staff go?','Hay una alerta de tornado (warning) en la zona durante tu turno. ¿A dónde van huéspedes y personal?','["An interior room or hallway on the lowest floor, away from windows", "The pool deck", "The parking lot to watch it", "An upper-floor room with big windows"]'::jsonb,'["Un cuarto o pasillo interior en el piso más bajo, lejos de ventanas", "A la alberca", "Al estacionamiento para verlo", "Un cuarto en piso alto con ventanales"]'::jsonb,0,'NWS: get to the lowest floor, an interior room away from windows.','El NWS dice: ve al piso más bajo, a un cuarto interior lejos de ventanas.','https://www.weather.gov/safety/tornado',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['tornado','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tornado','What''s the difference between a tornado WATCH and a tornado WARNING?','¿Cuál es la diferencia entre un ''watch'' y un ''warning'' de tornado?','["Watch means a tornado already hit", "They mean the same thing", "Watch = conditions are possible; Warning = a tornado is happening or imminent — take shelter now", "Warning is less serious"]'::jsonb,'["''Watch'' significa que ya pegó", "Significan lo mismo", "''Watch'' = puede formarse; ''warning'' = hay tornado o está por llegar; refúgiate ya", "El ''warning'' es menos grave"]'::jsonb,2,'NWS defines a watch as ''be prepared'' and a warning as ''take action''.','El NWS: ''watch'' = prepárate; ''warning'' = actúa ya.','https://www.weather.gov/safety/tornado',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['tornado','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tornado','Minnesota tests outdoor sirens at 1 p.m. on the first Wednesday of the month. If sirens sound at any other time, you should…','En Minnesota las sirenas se prueban el primer miércoles del mes a la 1 p. m. Si suenan en otro momento, debes…','["Ignore it — it''s a test", "Treat it as real and go to shelter", "Go outside to look", "Call 911 to ask"]'::jsonb,'["Ignorarlo; es prueba", "Tomarlo como real e ir al refugio", "Salir a ver", "Llamar al 911 para preguntar"]'::jsonb,1,'Sirens outside the scheduled test mean take shelter and check official info.','Si suenan fuera de la prueba, refúgiate y revisa información oficial.','https://www.weather.gov/safety/tornado',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['tornado','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lightning','You''re outside (lot, dumpster, pool deck) and hear thunder. What should you do?','Estás afuera (estacionamiento, basura, alberca) y oyes truenos. ¿Qué haces?','["Finish the task first", "Wait until you see lightning", "Stand under a tall tree", "Go inside right away — if you can hear thunder, you can be struck"]'::jsonb,'["Terminar primero", "Esperar a ver el rayo", "Ponerte bajo un árbol alto", "Entrar de inmediato; si oyes truenos, te puede caer un rayo"]'::jsonb,3,'NWS: ''When thunder roars, go indoors.''','El NWS: cuando truena, entra.','https://www.weather.gov/safety/lightning',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['lightning','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lightning','After the last thunder, how long should you wait before going back outside?','Después del último trueno, ¿cuánto esperas para volver a salir?','["2 minutes", "30 minutes", "No need to wait", "Until the rain stops"]'::jsonb,'["2 minutos", "30 minutos", "No hay que esperar", "Hasta que pare la lluvia"]'::jsonb,1,'NWS recommends waiting 30 minutes after the last thunder.','El NWS recomienda esperar 30 minutos tras el último trueno.','https://www.weather.gov/safety/lightning',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['lightning','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cold','Wind chill is −30°F. About how fast can frostbite happen on exposed skin?','La sensación térmica es de −30°F. ¿Qué tan rápido puede haber congelación en piel expuesta?','["In about 30 minutes or less", "Only after several hours", "It can''t happen above −50°F", "Only if you''re wet"]'::jsonb,'["En unos 30 minutos o menos", "Solo tras varias horas", "No pasa arriba de −50°F", "Solo si estás mojado"]'::jsonb,0,'NWS wind chill charts show frostbite in 30 minutes or less at these levels.','Las tablas del NWS muestran congelación en 30 minutos o menos a ese nivel.','https://www.weather.gov/safety/cold-wind-chill-warning',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['cold','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cold','Which is an early sign of frostbite?','¿Cuál es una señal temprana de congelación?','["Red, itchy rash on the back", "Sneezing", "Numb skin that looks white or grayish", "Sweating"]'::jsonb,'["Sarpullido rojo en la espalda", "Estornudos", "Piel entumida, blanca o grisácea", "Sudor"]'::jsonb,2,'Numbness and white/grayish-yellow skin are early frostbite signs (CDC/NWS).','Entumecimiento y piel blanca o grisácea son señales tempranas.','https://www.osha.gov/winter-weather',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['cold','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cold','A coworker who''s been outside is shivering hard, confused and slurring words. What could it be?','Un compañero que estuvo afuera tiembla mucho, está confundido y arrastra las palabras. ¿Qué podría ser?','["A cold", "Food allergy", "Hypothermia — get them warm and call for help", "Just tiredness"]'::jsonb,'["Un resfriado", "Alergia", "Hipotermia; abrígalo y pide ayuda", "Solo cansancio"]'::jsonb,2,'Shivering, confusion and slurred speech are hypothermia signs. It''s an emergency.','Temblores, confusión y habla arrastrada son señales de hipotermia. Es emergencia.','https://www.osha.gov/winter-weather',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['cold','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','heat','On a hot day, a coworker stops sweating, is confused and has hot skin. What do you do?','En un día caluroso, un compañero deja de sudar, está confundido y tiene la piel caliente. ¿Qué haces?','["Give them coffee", "Wrap them in a blanket", "Call 911 and cool them right away — it may be heat stroke", "Tell them to keep working"]'::jsonb,'["Darle café", "Taparlo con una cobija", "Llamar al 911 y enfriarlo de inmediato; puede ser golpe de calor", "Decirle que siga trabajando"]'::jsonb,2,'OSHA: heat stroke is a medical emergency — call 911 and cool the worker.','OSHA: el golpe de calor es emergencia; llama al 911 y enfríalo.','https://www.osha.gov/heat-exposure',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['heat','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cpr','An adult collapses and isn''t breathing normally. After calling 911, what do you start?','Un adulto se desmaya y no respira normal. Después de llamar al 911, ¿qué empiezas?','["Hard, fast chest compressions in the center of the chest", "Wait for the ambulance", "Slap their face", "Give them water"]'::jsonb,'["Compresiones fuertes y rápidas en el centro del pecho", "Esperar la ambulancia", "Darle cachetadas", "Darle agua"]'::jsonb,0,'AHA Hands-Only CPR: call 911, then push hard and fast in the center of the chest.','RCP solo con manos de la AHA: llama al 911 y presiona fuerte y rápido en el centro del pecho.','https://www.heart.org/en/cpr',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['cpr','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cpr','About how fast should chest compressions be during CPR?','¿Qué tan rápido deben ser las compresiones en RCP?','["200–250 per minute", "One every 10 seconds", "20 per minute", "100–120 per minute"]'::jsonb,'["200 a 250 por minuto", "Una cada 10 segundos", "20 por minuto", "100 a 120 por minuto"]'::jsonb,3,'AHA recommends 100–120 compressions per minute.','La AHA recomienda 100 a 120 compresiones por minuto.','https://www.heart.org/en/cpr',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','hard',array['cpr','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','aed','Someone brings the AED to a collapsed guest. What do you do first?','Alguien trae el desfibrilador a un huésped desmayado. ¿Qué haces primero?','["Read the whole manual", "Wait for a manager to approve", "Turn it on and follow the voice prompts", "Put it under their head"]'::jsonb,'["Leer todo el manual", "Esperar a que un gerente apruebe", "Encenderlo y seguir las instrucciones de voz", "Ponerlo bajo la cabeza"]'::jsonb,2,'Red Cross: turn on the AED and follow its prompts.','Cruz Roja: enciende el DEA y sigue sus instrucciones.','https://www.redcross.org/take-a-class/aed/using-an-aed',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['aed','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','aed','When the AED says it''s analyzing or about to shock, you should…','Cuando el DEA dice que está analizando o va a dar descarga, debes…','["Make sure no one is touching the person", "Hold their hand", "Pour water on the chest", "Keep doing compressions"]'::jsonb,'["Asegurarte de que nadie toque a la persona", "Tomarle la mano", "Echarle agua en el pecho", "Seguir con compresiones"]'::jsonb,0,'Everyone must ''stand clear'' during analysis and shock.','Todos deben alejarse durante el análisis y la descarga.','https://www.redcross.org/take-a-class/aed/using-an-aed',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['aed','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','choking','An adult is choking and can''t speak, cough or breathe. What does the Red Cross teach?','Un adulto se está ahogando y no puede hablar, toser ni respirar. ¿Qué enseña la Cruz Roja?','["Give them water", "Give back blows and abdominal thrusts, and call 911", "Wait — it''ll pass", "Lay them down for a nap"]'::jsonb,'["Darle agua", "Dar golpes en la espalda y compresiones abdominales, y llamar al 911", "Esperar a que pase", "Acostarlo a dormir"]'::jsonb,1,'Red Cross: 5 back blows and 5 abdominal thrusts, repeat; call 911.','Cruz Roja: 5 golpes en la espalda y 5 compresiones abdominales, repetir; llamar al 911.','https://www.redcross.org/take-a-class/resources/learn-first-aid/adult-child-choking',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['choking','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','choking','A guest is coughing hard but can still talk. What should you do?','Un huésped tose fuerte pero puede hablar. ¿Qué haces?','["Start abdominal thrusts right away", "Hit them hard on the back", "Give them bread", "Encourage them to keep coughing and stay with them"]'::jsonb,'["Hacer compresiones abdominales de inmediato", "Pegarle fuerte en la espalda", "Darle pan", "Animarlo a seguir tosiendo y quedarte con él"]'::jsonb,3,'If they can cough forcefully or talk, let them cough; act if they can''t.','Si puede toser fuerte o hablar, deja que tosa; actúa si ya no puede.','https://www.redcross.org/take-a-class/resources/learn-first-aid/adult-child-choking',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['choking','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stroke','In stroke warning signs, what does F.A.S.T. stand for?','En las señales de derrame (embolia), ¿qué significa F.A.S.T.?','["Food, Air, Sleep, Temperature", "Fever, Aches, Sneezing, Tiredness", "Face drooping, Arm weakness, Speech difficulty, Time to call 911", "Fall, Ankle, Shoulder, Twist"]'::jsonb,'["Comida, aire, sueño, temperatura", "Fiebre, dolores, estornudos, cansancio", "Cara caída, brazo débil, dificultad al hablar, tiempo de llamar al 911", "Caída, tobillo, hombro, torcedura"]'::jsonb,2,'American Stroke Association: F.A.S.T.','Asociación Americana de Derrame: F.A.S.T.','https://www.stroke.org/en/about-stroke/stroke-symptoms',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['stroke','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stroke','A guest suddenly has a drooping face and slurred speech. What''s your first move?','Un huésped de pronto tiene la cara caída y habla arrastrado. ¿Qué haces primero?','["Tell them to lie down and check later", "Give them aspirin and leave", "Call 911 right away and note the time it started", "Drive them home"]'::jsonb,'["Decirle que se acueste y revisar después", "Darle aspirina y irte", "Llamar al 911 de inmediato y anotar la hora en que empezó", "Llevarlo a su casa"]'::jsonb,2,'Stroke is time-critical: call 911 and note when symptoms began.','El derrame es urgente: llama al 911 y anota cuándo empezó.','https://www.stroke.org/en/about-stroke/stroke-symptoms',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['stroke','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','burns','What''s the right first aid for a minor burn?','¿Cuál es el primer auxilio para una quemadura leve?','["Put butter on it", "Pop the blisters", "Put ice directly on it", "Cool it under cool (not icy) running water"]'::jsonb,'["Ponerle mantequilla", "Reventar las ampollas", "Ponerle hielo directo", "Enfriarla con agua corriente fresca (no helada)"]'::jsonb,3,'Mayo Clinic: cool with cool running water; no ice, no butter; don''t break blisters.','Mayo Clinic: enfría con agua fresca; sin hielo ni mantequilla; no revientes ampollas.','https://www.mayoclinic.org/first-aid/first-aid-burns/basics/art-20056649',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['burns','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ada','A guest has a dog and you aren''t sure it''s a service animal. Under the ADA, what may you ask?','Un huésped trae un perro y no sabes si es de servicio. Según la ADA, ¿qué puedes preguntar?','["Is it required because of a disability, and what task is it trained to do?", "Show me its ID card", "What is your disability?", "Can it perform a trick?"]'::jsonb,'["¿Es necesario por una discapacidad y qué tarea está entrenado para hacer?", "Muéstreme su credencial", "¿Cuál es su discapacidad?", "¿Puede hacer un truco?"]'::jsonb,0,'ADA allows only these two questions; you can''t ask for papers or about the disability.','La ADA solo permite esas dos preguntas; no puedes pedir papeles ni preguntar por la discapacidad.','https://www.ada.gov/resources/service-animals-2010-requirements/',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['ada','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ada','Under the ADA, when can a service animal be asked to leave?','Según la ADA, ¿cuándo se puede pedir que salga un animal de servicio?','["If another guest is afraid of dogs", "If it''s out of control and the handler doesn''t fix it, or it isn''t housebroken", "Never, under any situation", "If it''s a large breed"]'::jsonb,'["Si otro huésped les tiene miedo", "Si está fuera de control y el dueño no lo corrige, o si no está entrenado para ir al baño", "Nunca, en ningún caso", "Si es de raza grande"]'::jsonb,1,'ADA: only for being out of control or not housebroken.','ADA: solo si está fuera de control o no está entrenado para el baño.','https://www.ada.gov/resources/service-animals-2010-requirements/',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['ada','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ada','Can we charge a pet fee for a service animal?','¿Podemos cobrar cargo de mascota por un animal de servicio?','["Only on weekends", "No — but the guest can be charged for actual damage, like any guest", "Yes, the normal pet fee", "Yes, double"]'::jsonb,'["Solo en fin de semana", "No; pero sí se puede cobrar un daño real, como a cualquier huésped", "Sí, el cargo normal", "Sí, el doble"]'::jsonb,1,'ADA: no pet fees or deposits for service animals; damage can be charged if you''d charge others.','ADA: no se cobra cargo ni depósito por animales de servicio; los daños sí, igual que a otros.','https://www.ada.gov/resources/service-animals-2010-requirements/',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['ada','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trafficking','Which could be a sign of human trafficking at a hotel?','¿Cuál podría ser señal de trata de personas en un hotel?','["A guest who seems controlled by someone else and won''t speak for themselves", "A guest asking for extra towels", "A business traveler with a laptop", "A family checking in with kids"]'::jsonb,'["Un huésped que parece controlado por otra persona y no habla por sí mismo", "Un huésped que pide toallas extra", "Un viajero de negocios con laptop", "Una familia con niños"]'::jsonb,0,'DHS Blue Campaign lists signs like being controlled, fearful, or not speaking for themselves.','La Campaña Azul del DHS menciona señales como estar controlado, con miedo, o no hablar por sí mismo.','https://www.dhs.gov/blue-campaign',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['trafficking','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trafficking','You suspect trafficking. What should you do?','Sospechas trata de personas. ¿Qué haces?','["Confront the person yourself", "Ignore it", "Don''t confront anyone — tell your manager, and call 911 if someone is in danger", "Post about it online"]'::jsonb,'["Enfrentar tú a la persona", "Ignorarlo", "No enfrentes a nadie; avisa a tu gerente y llama al 911 si hay peligro", "Publicarlo en redes"]'::jsonb,2,'DHS advises not confronting; report. Call 911 for emergencies.','El DHS aconseja no enfrentar y reportar. En emergencia, 911.','https://www.dhs.gov/blue-campaign',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['trafficking','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','harassment','A guest makes repeated sexual comments to you. What should you do?','Un huésped te hace comentarios sexuales repetidos. ¿Qué haces?','["Fight back", "Leave the situation if you can and report it to your manager", "Keep quiet so you don''t cause trouble", "Quit on the spot"]'::jsonb,'["Pelear", "Salir de la situación si puedes y reportarlo a tu gerente", "Callarte para no causar problemas", "Renunciar en ese momento"]'::jsonb,1,'Employers must address harassment, including by guests (EEOC). Report it.','El empleador debe atender el acoso, aun de huéspedes (EEOC). Repórtalo.','https://www.eeoc.gov/harassment',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['harassment','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','harassment','Can you be punished for reporting harassment in good faith?','¿Te pueden castigar por reportar acoso de buena fe?','["Yes, if the guest complains", "Yes, after 3 reports", "No — retaliation for reporting is illegal", "Only if you''re new"]'::jsonb,'["Sí, si el huésped se queja", "Sí, después de 3 reportes", "No; las represalias por reportar son ilegales", "Solo si eres nuevo"]'::jsonb,2,'EEOC: retaliation for reporting or participating is prohibited.','EEOC: está prohibido tomar represalias por reportar o participar.','https://www.eeoc.gov/retaliation',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['harassment','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','breaks','Under Minnesota law (since 2026), how often do you get a rest break?','Según la ley de Minnesota (desde 2026), ¿cada cuándo tienes un descanso?','["Only one per day", "At least 15 minutes for every 4 consecutive hours worked", "Only after 8 hours", "None required"]'::jsonb,'["Solo uno al día", "Al menos 15 minutos por cada 4 horas seguidas", "Solo después de 8 horas", "No es obligatorio"]'::jsonb,1,'MN DLI: a paid rest break of at least 15 minutes, or 15% of the time, every 4 consecutive hours.','DLI de MN: un descanso pagado de al menos 15 minutos (o 15%) cada 4 horas seguidas.','https://dli.mn.gov/breaks',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['breaks','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','breaks','In Minnesota, when are you owed a 30-minute meal break?','En Minnesota, ¿cuándo te toca una comida de 30 minutos?','["Never", "Only after 10 hours", "Only on double shifts", "When you work 6 or more consecutive hours"]'::jsonb,'["Nunca", "Solo después de 10 horas", "Solo en turnos dobles", "Cuando trabajas 6 horas o más seguidas"]'::jsonb,3,'MN DLI: at least 30 minutes for 6+ consecutive hours.','DLI de MN: al menos 30 minutos por 6 o más horas seguidas.','https://dli.mn.gov/breaks',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['breaks','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','esst','How do you earn Minnesota sick and safe time (ESST)?','¿Cómo se acumula el tiempo por enfermedad y seguridad (ESST) en Minnesota?','["1 hour for every 30 hours worked", "1 day per year only", "1 hour per 100 hours", "Only managers get it"]'::jsonb,'["1 hora por cada 30 horas trabajadas", "Solo 1 día al año", "1 hora por cada 100 horas", "Solo los gerentes"]'::jsonb,0,'MN DLI: at least 1 hour per 30 hours worked, up to at least 48 hours a year.','DLI de MN: al menos 1 hora por 30 horas, hasta al menos 48 horas al año.','https://www.dli.mn.gov/sick-leave-FAQs',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['esst','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','esst','Can you use ESST to care for a sick child?','¿Puedes usar ESST para cuidar a un hijo enfermo?','["No, only your own illness", "Yes — ESST covers caring for a family member", "Only with 2 weeks'' notice", "Only if they''re hospitalized"]'::jsonb,'["No, solo para ti", "Sí; el ESST cubre cuidar a un familiar", "Solo con 2 semanas de aviso", "Solo si está hospitalizado"]'::jsonb,1,'MN DLI: ESST can be used for a family member''s illness, care or treatment.','DLI de MN: el ESST se puede usar para enfermedad o cuidado de un familiar.','https://www.dli.mn.gov/sick-leave-FAQs',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['esst','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','esst','Up to how many unused ESST hours can carry over to next year?','¿Hasta cuántas horas de ESST sin usar pasan al siguiente año?','["500 hours", "80 hours (unless the employer allows more)", "None", "8 hours"]'::jsonb,'["500 horas", "80 horas (salvo que el empleador permita más)", "Ninguna", "8 horas"]'::jsonb,1,'MN DLI: carryover up to 80 hours, unless a higher cap is allowed.','DLI de MN: se acumulan hasta 80 horas, salvo un tope mayor.','https://www.dli.mn.gov/sick-leave-FAQs',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','hard',array['esst','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','injury','You get hurt at work, even a little. When should you report it?','Te lastimas en el trabajo, aunque sea poco. ¿Cuándo lo reportas?','["Never — it''ll look bad", "Right away, to your supervisor", "At your yearly review", "Only if it still hurts next week"]'::jsonb,'["Nunca; se ve mal", "De inmediato, a tu supervisor", "En tu evaluación anual", "Solo si sigue doliendo la otra semana"]'::jsonb,1,'Early reporting protects your workers'' comp claim (MN DLI).','Reportar pronto protege tu reclamo de compensación (DLI de MN).','https://www.dli.mn.gov/workers-compensation',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['injury','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','injury','Who pays medical bills for a work injury in Minnesota?','¿Quién paga las cuentas médicas de una lesión de trabajo en Minnesota?','["Workers'' compensation insurance through the employer", "The guest", "Nobody", "You always pay"]'::jsonb,'["El seguro de compensación del empleador", "El huésped", "Nadie", "Siempre pagas tú"]'::jsonb,0,'MN workers'' comp covers medical costs and some lost wages.','La compensación en MN cubre gastos médicos y parte del salario perdido.','https://www.dli.mn.gov/workers-compensation',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['injury','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','osha','Can you file a safety complaint with OSHA about a hazard at work?','¿Puedes poner una queja de seguridad ante OSHA por un peligro en el trabajo?','["Yes, and the law protects you from retaliation", "Only if you''re a manager", "No", "Only after someone is hurt"]'::jsonb,'["Sí, y la ley te protege de represalias", "Solo si eres gerente", "No", "Solo si alguien sale lastimado"]'::jsonb,0,'OSHA: workers can file complaints and are protected from retaliation.','OSHA: los trabajadores pueden quejarse y están protegidos de represalias.','https://www.osha.gov/workers/file-complaint',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['osha','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','osha','Do you have a right to safety training in a language you understand?','¿Tienes derecho a capacitación de seguridad en un idioma que entiendas?','["Only for chemicals", "Only if you ask twice", "Yes", "No, English only"]'::jsonb,'["Solo para químicos", "Solo si pides dos veces", "Sí", "No, solo en inglés"]'::jsonb,2,'OSHA: training must be in a language and vocabulary workers understand.','OSHA: la capacitación debe ser en un idioma que el trabajador entienda.','https://www.osha.gov/workers',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['osha','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Where can you find a chemical''s hazards and first aid?','¿Dónde encuentras los peligros y primeros auxilios de un químico?','["The sales receipt", "The guest comment card", "The Safety Data Sheet (SDS) and the label", "Nowhere"]'::jsonb,'["El recibo de compra", "La tarjeta de comentarios", "La Hoja de Datos de Seguridad (SDS) y la etiqueta", "En ningún lado"]'::jsonb,2,'OSHA HazCom requires labels and SDSs to be available.','HazCom de OSHA exige etiquetas y SDS disponibles.','https://www.osha.gov/hazcom',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['chemicals','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sharps','You find a used needle in a room or trash. What do you do?','Encuentras una aguja usada en un cuarto o la basura. ¿Qué haces?','["Throw it in the regular trash", "Recap it", "Put it in your pocket", "Don''t touch it bare-handed — tell your supervisor and use a sharps container"]'::jsonb,'["Tirarla a la basura normal", "Ponerle el tapón", "Guardarla en la bolsa", "No tocarla con la mano; avisa a tu supervisor y usa contenedor de punzocortantes"]'::jsonb,3,'OSHA bloodborne pathogens: never recap; use sharps containers.','OSHA patógenos en sangre: nunca tapes la aguja; usa contenedor.','https://www.osha.gov/bloodborne-pathogens',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['sharps','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sharps','You get stuck by a used needle. What''s the first thing to do?','Te pinchas con una aguja usada. ¿Qué haces primero?','["Wait to see if it hurts", "Wash with soap and water and report it right away for medical evaluation", "Put on a bandage and forget it", "Squeeze it and keep working"]'::jsonb,'["Esperar a ver si duele", "Lavar con agua y jabón y reportarlo de inmediato para evaluación médica", "Ponerte una curita y olvidarlo", "Apretarla y seguir trabajando"]'::jsonb,1,'CDC/OSHA: wash, report immediately, get medical follow-up.','CDC/OSHA: lava, reporta de inmediato y busca atención médica.','https://www.osha.gov/bloodborne-pathogens',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','hard',array['sharps','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','slips','You see a spill in a hallway. What''s right?','Ves algo derramado en un pasillo. ¿Qué es lo correcto?','["Leave it for the next shift", "Cover it with a towel and leave", "Put out a wet-floor sign and clean it or call someone right away", "Walk around it"]'::jsonb,'["Dejarlo al siguiente turno", "Taparlo con una toalla e irte", "Poner señal de piso mojado y limpiarlo o avisar de inmediato", "Rodearlo"]'::jsonb,2,'OSHA: keep walking surfaces clean and dry; warn of hazards.','OSHA: mantener superficies limpias y secas; avisar del peligro.','https://www.osha.gov/walking-working-surfaces',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['slips','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','You discover a fire. What do you do first?','Descubres un incendio. ¿Qué haces primero?','["Use the elevator to leave", "Open windows", "Pull the alarm, call 911, and get out", "Finish what you''re doing"]'::jsonb,'["Bajar en elevador", "Abrir ventanas", "Activar la alarma, llamar al 911 y salir", "Terminar lo que haces"]'::jsonb,2,'Alert, call, evacuate. Never use elevators in a fire.','Alerta, llama y evacúa. Nunca uses el elevador en un incendio.','https://www.osha.gov/etools/evacuation-plans-procedures',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['fire','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fire','A hallway door is propped open with a wedge. It''s a fire door. What do you do?','Una puerta de pasillo está detenida con una cuña. Es puerta contra incendio. ¿Qué haces?','["Add another wedge", "Remove the wedge — fire doors must close on their own", "Leave it, it''s convenient", "Tape it open"]'::jsonb,'["Poner otra cuña", "Quitar la cuña; las puertas contra incendio deben cerrar solas", "Dejarla, es práctico", "Pegarla abierta con cinta"]'::jsonb,1,'Fire doors stop smoke and fire spread and must not be propped open.','Las puertas contra incendio frenan humo y fuego; no se dejan abiertas.','https://www.osha.gov/exit-routes',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['fire','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','exits','Can boxes or carts be stored in an exit stairwell?','¿Se pueden guardar cajas o carros en una escalera de salida?','["Yes, if it''s short-term", "Only at night", "Only linen carts", "No — exit routes must stay clear"]'::jsonb,'["Sí, por poco tiempo", "Solo de noche", "Solo carros de ropa", "No; las rutas de salida deben estar libres"]'::jsonb,3,'OSHA: exit routes must be free of obstructions.','OSHA: las rutas de salida deben estar libres.','https://www.osha.gov/exit-routes',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['exits','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest asks you something you don''t know (not your department). Best answer?','Un huésped te pregunta algo que no sabes (no es tu área). ¿Mejor respuesta?','["''Let me find out for you'' — then get the answer or walk them to someone who knows", "''Not my job''", "Ignore them", "Guess"]'::jsonb,'["''Déjeme averiguarlo'' y luego conseguir la respuesta o llevarlo con alguien que sepa", "''No es mi trabajo''", "Ignorarlo", "Adivinar"]'::jsonb,0,'Owning the request, even if you hand it off, is basic hospitality.','Hacerte cargo, aunque lo pases a otro, es lo básico de la hospitalidad.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['service','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','service','A guest is upset about a problem. What helps most first?','Un huésped está molesto por un problema. ¿Qué ayuda más primero?','["Explain why it''s not your fault", "Walk away until they calm down", "Interrupt with policy", "Listen fully, apologize for the experience, then fix it or get help"]'::jsonb,'["Explicar que no es tu culpa", "Irte hasta que se calme", "Interrumpir con la política", "Escuchar todo, disculparte por la experiencia y luego resolver o pedir ayuda"]'::jsonb,3,'Listen–apologize–solve is a common service-recovery approach.','Escuchar, disculparse y resolver es la forma común de recuperar el servicio.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['service','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','Someone in a hallway asks you to open a room because they ''lost their key.'' What do you do?','Alguien en el pasillo te pide abrir un cuarto porque ''perdió su llave''. ¿Qué haces?','["Politely send them to the front desk to verify ID", "Ask the room number and open it", "Open it — they seem nice", "Lend them your master key"]'::jsonb,'["Mandarlo amablemente a recepción para verificar identificación", "Preguntar el número y abrir", "Abrir, se ve amable", "Prestarle tu llave maestra"]'::jsonb,0,'Never let anyone into a room without front-desk verification.','Nunca dejes entrar a nadie a un cuarto sin verificación de recepción.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['security','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','security','You lose your master key card. What do you do?','Pierdes tu llave maestra. ¿Qué haces?','["Make a copy", "Report it to your supervisor right away so it can be deactivated", "Borrow a coworker''s", "Wait to see if it turns up"]'::jsonb,'["Sacar copia", "Reportarlo de inmediato a tu supervisor para desactivarla", "Pedir la de un compañero", "Esperar a ver si aparece"]'::jsonb,1,'A lost master key is a security risk; it must be cancelled quickly.','Una llave maestra perdida es un riesgo; hay que cancelarla rápido.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','med',array['security','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','teamwork','Your shift is ending and a task isn''t done. What''s best?','Tu turno termina y una tarea no está lista. ¿Qué es lo mejor?','["Leave and say nothing", "Mark it done", "Tell your supervisor or the next shift exactly what''s left", "Hide it"]'::jsonb,'["Irte sin decir nada", "Marcarlo como hecho", "Decirle a tu supervisor o al siguiente turno exactamente qué falta", "Esconderlo"]'::jsonb,2,'A clear handoff keeps guests from falling through the cracks.','Una entrega clara evita que se le olvide algo al huésped.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['teamwork','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','radio','Why keep radio calls short and clear?','¿Por qué hablar corto y claro por radio?','["To sound cool", "It saves battery only", "It''s not important", "Others may need the channel for urgent calls, and guests may hear"]'::jsonb,'["Para sonar bien", "Solo ahorra batería", "No importa", "Otros pueden necesitar el canal para algo urgente y los huéspedes pueden oír"]'::jsonb,3,'Short, clear radio use keeps the channel free for emergencies.','Hablar corto deja el canal libre para emergencias.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['radio','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','privacy','A caller asks what room a guest is in. What do you do?','Alguien llama y pregunta en qué cuarto está un huésped. ¿Qué haces?','["Never give room numbers — offer to connect them or take a message", "Give it if they know the name", "Give it to family", "Text it to them"]'::jsonb,'["Nunca dar el número; ofrecer transferir o tomar recado", "Darlo si sabe el nombre", "Darlo a familiares", "Mandarlo por mensaje"]'::jsonb,0,'Guest room numbers are private for safety.','El número de cuarto es privado por seguridad.','general hospitality best practice',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['privacy','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','mn_weather','In a Minnesota winter, what helps most to prevent falls outside?','En el invierno de Minnesota, ¿qué ayuda más a evitar caídas afuera?','["Running to get inside fast", "Short, flat-footed ''penguin'' steps and shoes with good grip", "Hands in pockets", "Looking at your phone"]'::jsonb,'["Correr para entrar rápido", "Pasos cortos y planos ''de pingüino'' y zapatos con buen agarre", "Manos en las bolsas", "Ir viendo el celular"]'::jsonb,1,'OSHA winter guidance: proper footwear and short, careful steps on ice.','OSHA invierno: calzado adecuado y pasos cortos en el hielo.','https://www.osha.gov/winter-weather',array['bartender','breakfast','driver','hk_supervisor','houseman','laundry','maintenance','room_attendant']::text[],'shared','easy',array['mn_weather','bartender','breakfast','driver','housekeeping','houseman','laundry','maintenance']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','headlights','When does Minnesota law require headlights?','¿Cuándo exige la ley de Minnesota encender los faros?','["Only after midnight", "Sunset to sunrise, in rain/snow/sleet/hail, or when you can''t see 500 feet", "Only in fog", "Only on highways"]'::jsonb,'["Solo después de medianoche", "Del atardecer al amanecer, con lluvia, nieve, aguanieve o granizo, o si no ves a 500 pies", "Solo con neblina", "Solo en autopista"]'::jsonb,1,'MN Stat. 169.48.','Estatuto 169.48 de MN.','https://www.revisor.mn.gov/statutes/cite/169.48',array['driver']::text[],'role','easy',array['headlights','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','headlights','It''s 2 p.m. and lightly snowing. Do you need headlights on in Minnesota?','Son las 2 p. m. y nieva poco. ¿Debes llevar faros encendidos en Minnesota?','["Only if it''s heavy", "Only parking lights", "No, it''s daytime", "Yes — snow requires headlights"]'::jsonb,'["Solo si es fuerte", "Solo cuartos", "No, es de día", "Sí; con nieve son obligatorios"]'::jsonb,3,'169.48 requires headlights during snow, rain, sleet or hail.','El 169.48 exige faros con nieve, lluvia, aguanieve o granizo.','https://www.revisor.mn.gov/statutes/cite/169.48',array['driver']::text[],'role','med',array['headlights','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','headlights','When must you dim your high beams for an oncoming car?','¿Cuándo debes bajar las luces altas por un carro que viene?','["Never", "Within 50 feet", "Only in town", "Within 1,000 feet of the oncoming vehicle"]'::jsonb,'["Nunca", "A 50 pies", "Solo en la ciudad", "A 1,000 pies del vehículo que viene"]'::jsonb,3,'MN 169.61: dim within 1,000 ft of oncoming and 200 ft when following.','MN 169.61: baja a 1,000 pies de quien viene y a 200 si vas detrás.','https://www.revisor.mn.gov/statutes/cite/169.61',array['driver']::text[],'role','med',array['headlights','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','move_over','A squad car with flashing lights is stopped on the shoulder. What must you do?','Una patrulla con luces está detenida en el acotamiento. ¿Qué debes hacer?','["Keep your speed and lane", "Honk", "Speed up to pass quickly", "Move over a lane if safe; if you can''t, slow down"]'::jsonb,'["Seguir igual", "Tocar el claxon", "Acelerar para pasar rápido", "Cambiarte de carril si es seguro; si no puedes, bajar la velocidad"]'::jsonb,3,'MN Move Over law (169.18), the Ted Foss law.','Ley ''Move Over'' de MN (169.18), Ley Ted Foss.','https://www.revisor.mn.gov/statutes/cite/169.18',array['driver']::text[],'role','easy',array['move_over','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','move_over','Does Minnesota''s Move Over law apply to a regular car stopped with hazard lights on?','¿La ley ''Move Over'' de MN aplica a un carro común detenido con intermitentes?','["No, only police", "Only tow trucks", "Yes — also for stalled vehicles with hazards or people outside", "Only on I-494"]'::jsonb,'["No, solo policía", "Solo grúas", "Sí; también a vehículos detenidos con intermitentes o gente afuera", "Solo en la I-494"]'::jsonb,2,'The law was expanded to stalled vehicles with hazard lights or people outside.','La ley se amplió a vehículos detenidos con intermitentes o gente afuera.','https://dps.mn.gov/divisions/ots/move-over',array['driver']::text[],'role','med',array['move_over','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hands_free','Under Minnesota''s hands-free law, can you hold your phone at a red light?','Según la ley de manos libres de MN, ¿puedes sostener el celular en un alto?','["Yes, at red lights", "Yes, under 5 mph", "Only for texting", "No — it applies whenever you''re driving, including stopped in traffic"]'::jsonb,'["Sí, en el alto", "Sí, a menos de 5 mph", "Solo para mensajes", "No; aplica siempre que manejas, incluso detenido en el tráfico"]'::jsonb,3,'MN DPS: no holding the phone while driving, including at stoplights.','DPS de MN: no sostener el celular manejando, ni en semáforos.','https://dps.mn.gov/divisions/ots/educational-materials/Pages/Hands-Free.aspx',array['driver']::text[],'role','easy',array['hands_free','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hands_free','Which phone use is allowed while driving the shuttle in Minnesota?','¿Qué uso del celular se permite al manejar el shuttle en MN?','["One-touch voice calls or GPS in hands-free mode", "Texting at stops", "Scrolling social media", "Watching a video"]'::jsonb,'["Llamadas o GPS con un toque en modo manos libres", "Mandar mensajes en los altos", "Ver redes sociales", "Ver videos"]'::jsonb,0,'MN law allows one-touch/voice activation; no texting, video or scrolling.','La ley permite activar con un toque o voz; no mensajes, videos ni redes.','https://dps.mn.gov/divisions/ots/educational-materials/Pages/Hands-Free.aspx',array['driver']::text[],'role','med',array['hands_free','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','hands_free','What''s the exception that lets a driver hold a phone in Minnesota?','¿Qué excepción permite sostener el celular al manejar en MN?','["Checking a guest''s flight", "Calling 911 in an emergency", "Taking a photo of traffic", "Being late"]'::jsonb,'["Revisar el vuelo de un huésped", "Llamar al 911 en una emergencia", "Tomar foto del tráfico", "Ir tarde"]'::jsonb,1,'Emergency calls are the key exception.','Las llamadas de emergencia son la excepción principal.','https://dps.mn.gov/divisions/ots/educational-materials/Pages/Hands-Free.aspx',array['driver']::text[],'role','hard',array['hands_free','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','seatbelts','Who in the shuttle must wear a seat belt in Minnesota?','¿Quién debe usar cinturón en el shuttle en Minnesota?','["Only the driver", "Only front seat", "The driver and all passengers in every seat with a belt", "Nobody under 20 mph"]'::jsonb,'["Solo el chofer", "Solo adelante", "El chofer y todos los pasajeros en asientos con cinturón", "Nadie a menos de 20 mph"]'::jsonb,2,'MN 169.686 requires belts for driver and passengers in all seats.','El 169.686 exige cinturón para chofer y pasajeros en todos los asientos.','https://www.revisor.mn.gov/statutes/cite/169.686',array['driver']::text[],'role','easy',array['seatbelts','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','school_bus','A school bus stops with red lights flashing and stop arm out. What do you do?','Un autobús escolar se detiene con luces rojas y el brazo de alto. ¿Qué haces?','["Honk and pass", "Only stop if kids are visible", "Pass slowly", "Stop at least 20 feet away and wait until lights stop and the arm is in"]'::jsonb,'["Tocar el claxon y pasar", "Solo parar si ves niños", "Pasar despacio", "Detenerte al menos a 20 pies y esperar a que apague luces y guarde el brazo"]'::jsonb,3,'MN 169.444: stop at least 20 ft away.','MN 169.444: detente al menos a 20 pies.','https://www.revisor.mn.gov/statutes/cite/169.444',array['driver']::text[],'role','easy',array['school_bus','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pedestrians','A pedestrian is in a crosswalk at an intersection without a signal. What must you do?','Un peatón está en el cruce en una esquina sin semáforo. ¿Qué haces?','["Go around them", "Honk", "Speed up", "Stop and let them cross"]'::jsonb,'["Rodearlo", "Tocar el claxon", "Acelerar", "Detenerte y dejarlo cruzar"]'::jsonb,3,'MN 169.21: drivers must stop for pedestrians in crosswalks.','MN 169.21: hay que parar por peatones en el cruce.','https://www.revisor.mn.gov/statutes/cite/169.21',array['driver']::text[],'role','easy',array['pedestrians','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pedestrians','A car is stopped at a crosswalk in the lane next to you. What should you do?','Un carro está detenido en el cruce en el carril de al lado. ¿Qué haces?','["Pass it quickly", "Change lanes and keep going", "Don''t pass it — someone may be crossing", "Honk at it"]'::jsonb,'["Rebasarlo rápido", "Cambiarte y seguir", "No rebasarlo; alguien podría estar cruzando", "Tocarle el claxon"]'::jsonb,2,'MN law prohibits passing a vehicle stopped for a pedestrian.','La ley prohíbe rebasar a un vehículo detenido por un peatón.','https://www.revisor.mn.gov/statutes/cite/169.21',array['driver']::text[],'role','med',array['pedestrians','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','speed','What''s the speed limit in a Minnesota urban district unless posted otherwise?','¿Cuál es el límite en zona urbana de MN si no hay letrero?','["20 mph", "55 mph", "30 mph", "45 mph"]'::jsonb,'["20 mph", "55 mph", "30 mph", "45 mph"]'::jsonb,2,'MN 169.14: 30 mph in urban districts.','MN 169.14: 30 mph en zonas urbanas.','https://www.revisor.mn.gov/statutes/cite/169.14',array['driver']::text[],'role','med',array['speed','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','speed','It''s snowing hard and the limit is 65. What speed is legal?','Nieva fuerte y el límite es 65. ¿Qué velocidad es legal?','["65 is always fine", "70 to keep up", "Exactly 55", "A speed safe for conditions — often well under the limit"]'::jsonb,'["65 siempre está bien", "70 para seguir el ritmo", "Exacto 55", "Una velocidad segura para las condiciones, muchas veces muy por debajo"]'::jsonb,3,'MN 169.14: no driver may drive faster than is reasonable for conditions.','MN 169.14: no se maneja más rápido de lo razonable para las condiciones.','https://www.revisor.mn.gov/statutes/cite/169.14',array['driver']::text[],'role','easy',array['speed','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','following','On dry roads, what following distance should you keep?','En pavimento seco, ¿qué distancia de seguimiento debes guardar?','["1 second", "10 feet", "At least 3 seconds — more in bad weather or with a van full", "Bumper to bumper"]'::jsonb,'["1 segundo", "10 pies", "Al menos 3 segundos; más con mal clima o van llena", "Pegado"]'::jsonb,2,'The 3-second rule is the standard in the MN Driver''s Manual.','La regla de 3 segundos es la del Manual del Conductor de MN.','https://dps.mn.gov/divisions/dvs',array['driver']::text[],'role','med',array['following','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','Before a winter drive, how much snow should you clear off the van?','Antes de manejar en invierno, ¿cuánta nieve debes quitar de la van?','["Only the driver window", "Just a small hole in the windshield", "None — it blows off", "All windows, mirrors, lights and the roof"]'::jsonb,'["Solo la ventana del chofer", "Solo un hoyito en el parabrisas", "Nada, se vuela", "Todas las ventanas, espejos, luces y el techo"]'::jsonb,3,'MnDOT/DPS urge clearing all snow and ice so you can see and be seen.','MnDOT y DPS piden quitar toda la nieve y hielo para ver y ser visto.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','easy',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','A snowplow is ahead of you. What''s safest?','Hay un quitanieves adelante. ¿Qué es lo más seguro?','["Flash your lights at it", "Follow close in its tracks", "Pass quickly on the right", "Stay well back and don''t pass on the right"]'::jsonb,'["Echarle luces", "Seguirlo pegado", "Rebasar rápido por la derecha", "Mantente lejos y no rebases por la derecha"]'::jsonb,3,'MnDOT: stay back from plows and never pass on the right.','MnDOT: mantente lejos y nunca rebases por la derecha.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','med',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','Where does black ice form first?','¿Dónde se forma primero el hielo negro?','["Bridges, overpasses and shaded spots", "Inside garages", "Sunny parking lots", "Gravel roads only"]'::jsonb,'["Puentes, pasos elevados y zonas de sombra", "Dentro de cocheras", "Estacionamientos con sol", "Solo caminos de grava"]'::jsonb,0,'Bridges and overpasses freeze before other road surfaces.','Los puentes se congelan antes que el resto del camino.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','med',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','Your van starts to skid on ice. What should you do?','Tu van empieza a patinar en hielo. ¿Qué haces?','["Accelerate", "Ease off the gas and steer gently where you want to go", "Turn the wheel hard the other way", "Slam the brakes"]'::jsonb,'["Acelerar", "Soltar el acelerador y girar suave hacia donde quieres ir", "Girar fuerte al lado contrario", "Frenar de golpe"]'::jsonb,1,'Standard skid recovery: off the gas, steer smoothly, no hard braking.','Para salir de un derrape: suelta el acelerador, gira suave, sin frenar fuerte.','https://dps.mn.gov/divisions/dvs',array['driver']::text[],'role','hard',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','With ABS brakes, how do you stop hard on ice?','Con frenos ABS, ¿cómo frenas fuerte en hielo?','["Use the parking brake", "Shift to neutral", "Pump the brakes fast", "Press firmly and hold — don''t pump"]'::jsonb,'["Usar el freno de mano", "Poner neutral", "Bombear rápido", "Presionar firme y mantener; no bombear"]'::jsonb,3,'NHTSA: with ABS, apply firm, steady pressure.','NHTSA: con ABS, presión firme y constante.','https://www.nhtsa.gov/road-safety',array['driver']::text[],'role','med',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','winter','What should the shuttle carry in a Minnesota winter?','¿Qué debe llevar el shuttle en invierno en Minnesota?','["Nothing extra", "A beach umbrella", "Only sunglasses", "Scraper/brush, blanket, and extra washer fluid"]'::jsonb,'["Nada extra", "Una sombrilla de playa", "Solo lentes oscuros", "Raspador/cepillo, cobija y líquido limpiaparabrisas extra"]'::jsonb,3,'MN DPS winter-kit guidance.','Guía de kit invernal de DPS MN.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','easy',array['winter','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tires','Why check tire pressure more often in winter?','¿Por qué revisar la presión de llantas más seguido en invierno?','["It doesn''t change", "Tires grow in the cold", "Snow inflates them", "Cold air lowers tire pressure"]'::jsonb,'["No cambia", "Las llantas crecen con el frío", "La nieve las infla", "El frío baja la presión"]'::jsonb,3,'NHTSA: pressure drops as temperatures fall.','NHTSA: la presión baja con el frío.','https://www.nhtsa.gov/equipment/tires',array['driver']::text[],'role','med',array['tires','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tires','Where do you find the right tire pressure for the van?','¿Dónde está la presión correcta para la van?','["Guess 50 psi", "The number on the tire sidewall (max)", "The sticker in the driver''s door jamb or the owner''s manual", "The gas station sign"]'::jsonb,'["Calcular 50 psi", "El número máximo del costado de la llanta", "La etiqueta en el marco de la puerta del chofer o el manual", "El letrero de la gasolinera"]'::jsonb,2,'NHTSA: use the vehicle placard, not the sidewall max.','NHTSA: usa la etiqueta del vehículo, no el máximo de la llanta.','https://www.nhtsa.gov/equipment/tires',array['driver']::text[],'role','easy',array['tires','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pretrip','Before your first run, what''s a quick walk-around check?','Antes del primer viaje, ¿qué se revisa al rodear la van?','["Tires, lights, mirrors, leaks and windows", "Only the gas cap", "Only the radio", "Nothing"]'::jsonb,'["Llantas, luces, espejos, fugas y vidrios", "Solo el tapón", "Solo el radio", "Nada"]'::jsonb,0,'A pre-trip inspection catches problems before passengers board.','La revisión previa detecta problemas antes de subir pasajeros.','https://www.fmcsa.dot.gov/regulations',array['driver']::text[],'role','easy',array['pretrip','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pretrip','You find a warning light on the dash before a run. What do you do?','Antes de salir ves un foco de advertencia prendido. ¿Qué haces?','["Cover it with tape", "Drive faster to finish", "Ignore it", "Report it to your manager before driving"]'::jsonb,'["Taparlo con cinta", "Manejar más rápido", "Ignorarlo", "Reportarlo a tu gerente antes de manejar"]'::jsonb,3,'Unsafe vehicle conditions should be reported and fixed before service.','Las fallas se reportan y se arreglan antes de dar servicio.','https://www.fmcsa.dot.gov/regulations',array['driver']::text[],'role','med',array['pretrip','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','drowsy','Which is a sign you''re too drowsy to drive?','¿Cuál es señal de que tienes demasiado sueño para manejar?','["Singing", "Feeling hungry", "Being early", "Drifting from your lane or missing exits"]'::jsonb,'["Cantar", "Tener hambre", "Llegar temprano", "Salirte del carril o pasarte salidas"]'::jsonb,3,'NHTSA drowsy-driving warning signs.','Señales de manejo con sueño, NHTSA.','https://www.nhtsa.gov/risky-driving/drowsy-driving',array['driver']::text[],'role','med',array['drowsy','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','distracted','A passenger hands you a phone to look at an address while driving. What do you do?','Un pasajero te da su celular para ver una dirección mientras manejas. ¿Qué haces?','["Speed up and look", "Pull over safely first, or have them read it out", "Hold it on the wheel", "Look while driving"]'::jsonb,'["Acelerar y ver", "Orillarte primero, o que te la lea", "Ponerlo en el volante", "Verlo manejando"]'::jsonb,1,'NHTSA: any visual distraction raises crash risk.','NHTSA: cualquier distracción visual aumenta el riesgo.','https://www.nhtsa.gov/risky-driving/distracted-driving',array['driver']::text[],'role','easy',array['distracted','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dui','What is Minnesota''s legal alcohol limit (BAC) for drivers 21+?','¿Cuál es el límite legal de alcohol (BAC) en MN para mayores de 21?','["No limit", "0.08", "0.15", "0.20"]'::jsonb,'["No hay límite", "0.08", "0.15", "0.20"]'::jsonb,1,'MN 169A.20: 0.08. For work, the rule is zero.','MN 169A.20: 0.08. En el trabajo, la regla es cero.','https://www.revisor.mn.gov/statutes/cite/169A.20',array['driver']::text[],'role','easy',array['dui','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dui','Can you drive the shuttle after taking a medicine that says ''may cause drowsiness''?','¿Puedes manejar el shuttle después de tomar medicina que dice ''puede causar sueño''?','["Only short trips", "Yes, it''s legal medicine", "Yes, with coffee", "No — tell your manager; impaired is impaired"]'::jsonb,'["Solo viajes cortos", "Sí, es medicina legal", "Sí, con café", "No; avisa a tu gerente; afectado es afectado"]'::jsonb,3,'MN DWI law covers impairment by drugs, including some prescriptions.','La ley de MN cubre la afectación por drogas, incluso recetadas.','https://www.revisor.mn.gov/statutes/cite/169A.20',array['driver']::text[],'role','med',array['dui','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','passengers','Where should guests stand while you load bags?','¿Dónde deben estar los huéspedes mientras subes maletas?','["On the bumper", "On the curb, away from the van''s path", "In the driving lane", "Behind the van"]'::jsonb,'["En la defensa", "En la banqueta, lejos del paso de la van", "En el carril", "Detrás de la van"]'::jsonb,1,'Keeping people clear of the vehicle prevents backing injuries.','Mantenerlos lejos evita accidentes al dar reversa.','general hospitality best practice',array['driver']::text[],'role','easy',array['passengers','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','passengers','A guest wants to stand while the shuttle moves because it''s a short ride. What do you say?','Un huésped quiere ir parado porque el viaje es corto. ¿Qué le dices?','["Ask them to sit and buckle before you move", "Hold the door", "It''s fine", "Only on the highway"]'::jsonb,'["Pedirle que se siente y se abroche antes de avanzar", "Que se agarre de la puerta", "Está bien", "Solo en autopista"]'::jsonb,0,'Seated and belted is required (169.686) and safest.','Ir sentado con cinturón es obligatorio (169.686) y más seguro.','https://www.revisor.mn.gov/statutes/cite/169.686',array['driver']::text[],'role','med',array['passengers','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','passengers','A guest in a wheelchair needs the shuttle and we can''t take it. What''s the right step?','Un huésped en silla de ruedas necesita el shuttle y no podemos llevarlo. ¿Qué es lo correcto?','["Tell them no", "Charge them extra", "Tell your manager right away so equivalent accessible transport can be arranged", "Make them wait until tomorrow"]'::jsonb,'["Decirle que no", "Cobrarle extra", "Avisar de inmediato al gerente para conseguir transporte accesible equivalente", "Que espere a mañana"]'::jsonb,2,'ADA requires equivalent service for guests with disabilities on hotel shuttles.','La ADA exige servicio equivalente para huéspedes con discapacidad.','https://www.ada.gov/resources/shuttle-service/',array['driver']::text[],'role','med',array['passengers','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','passengers','How should you help a guest with a cane step into the van?','¿Cómo ayudas a un huésped con bastón a subir a la van?','["Don''t offer", "Rush them", "Grab them and lift", "Ask how they''d like help, and offer an arm"]'::jsonb,'["No ofrecer", "Apurarlo", "Agarrarlo y cargarlo", "Preguntar cómo quiere ayuda y ofrecer el brazo"]'::jsonb,3,'Always ask before helping — people know what works for them.','Siempre pregunta antes de ayudar.','general hospitality best practice',array['driver']::text[],'role','easy',array['passengers','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','airport','Where do hotel shuttles pick up at MSP?','¿Dónde recogen los shuttles de hotel en MSP?','["The designated hotel shuttle area in the ground transportation center", "On Hwy 5", "In the parking ramp roof", "Any curb at departures"]'::jsonb,'["En la zona designada de shuttles de hotel en el centro de transporte terrestre", "En la Hwy 5", "En el techo del estacionamiento", "En cualquier banqueta de salidas"]'::jsonb,0,'MSP directs hotel shuttles to designated ground-transportation pickup areas.','MSP manda los shuttles a las zonas designadas de transporte terrestre.','https://www.mspairport.com/transportation',array['driver']::text[],'role','med',array['airport','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','airport','A guest calls for pickup from MSP. What info do you need?','Un huésped pide que lo recojan en MSP. ¿Qué datos necesitas?','["Name, terminal (1 or 2), number in the party and bags", "Their flight''s meal", "Only their name", "Their credit card"]'::jsonb,'["Nombre, terminal (1 o 2), cuántas personas y maletas", "La comida del vuelo", "Solo el nombre", "Su tarjeta"]'::jsonb,0,'MSP has Terminal 1 and Terminal 2 — knowing which saves time.','MSP tiene Terminal 1 y 2; saber cuál ahorra tiempo.','https://www.mspairport.com/transportation',array['driver']::text[],'role','easy',array['airport','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','airport','Which airlines use MSP Terminal 2?','¿Qué aerolíneas usan la Terminal 2 de MSP?','["Mainly Sun Country and Southwest (check the MSP site — it can change)", "All airlines", "No passenger flights", "Delta"]'::jsonb,'["Principalmente Sun Country y Southwest (revisa la página de MSP; puede cambiar)", "Todas", "Ningún vuelo de pasajeros", "Delta"]'::jsonb,0,'MSP lists Sun Country and Southwest at Terminal 2; Delta is at Terminal 1.','MSP indica Sun Country y Southwest en Terminal 2; Delta en Terminal 1.','https://www.mspairport.com/airlines-and-flights/airlines',array['driver']::text[],'role','med',array['airport','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','backing','What''s the safest way to back up the van?','¿Cuál es la forma más segura de dar reversa?','["Check around first, back slowly, use a spotter if you can''t see", "Rely only on the camera", "Back fast", "Honk and go"]'::jsonb,'["Revisar alrededor, reversa lenta y con alguien guiando si no ves", "Solo la cámara", "Reversa rápida", "Tocar el claxon y listo"]'::jsonb,0,'Most low-speed crashes happen backing; walk around and go slow.','Muchos choques son en reversa; revisa y ve despacio.','https://www.nhtsa.gov/road-safety',array['driver']::text[],'role','easy',array['backing','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','crash','You have a minor fender-bender with guests on board. First step?','Tienes un choque leve con huéspedes a bordo. ¿Primer paso?','["Post photos online", "Drive away", "Argue with the other driver", "Check for injuries, call 911 if needed, then call your manager"]'::jsonb,'["Subir fotos", "Irte", "Discutir con el otro", "Revisar lesionados, llamar al 911 si hace falta y luego al gerente"]'::jsonb,3,'MN law requires stopping and exchanging info; safety first.','La ley de MN exige parar e intercambiar datos; primero la seguridad.','https://www.revisor.mn.gov/statutes/cite/169.09',array['driver']::text[],'role','med',array['crash','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','crash','After a crash in Minnesota with injury or $1,000+ damage, who must be notified?','Tras un choque en MN con lesionados o daños de $1,000 o más, ¿a quién se avisa?','["Police right away (and a written report to DPS within 10 days)", "No one", "Only your insurance", "Only the guest"]'::jsonb,'["A la policía de inmediato (y reporte escrito a DPS en 10 días)", "A nadie", "Solo al seguro", "Solo al huésped"]'::jsonb,0,'MN 169.09: report to police; written report within 10 days for injury or $1,000+.','MN 169.09: aviso a la policía; reporte escrito en 10 días con lesiones o $1,000+.','https://www.revisor.mn.gov/statutes/cite/169.09',array['driver']::text[],'role','hard',array['crash','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','fuel','Why not let the shuttle''s tank run low in winter?','¿Por qué no dejar el tanque bajo en invierno?','["It saves money", "No reason", "You may get stuck in traffic or cold, and condensation can freeze lines", "It''s lighter"]'::jsonb,'["Ahorra dinero", "Por nada", "Te puedes quedar atorado con frío, y la humedad puede congelar líneas", "Pesa menos"]'::jsonb,2,'Keeping at least half a tank is common winter advice.','Mantener al menos medio tanque es consejo común de invierno.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','easy',array['fuel','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','idling','You wait 15 minutes at the airport curb. Should you leave the van running and walk away?','Esperas 15 minutos en el aeropuerto. ¿Dejas la van prendida y te alejas?','["No — never leave it running unattended", "Yes, with doors open", "Only at night", "Yes, to keep it warm"]'::jsonb,'["No; nunca la dejes prendida sola", "Sí, con puertas abiertas", "Solo de noche", "Sí, para que esté caliente"]'::jsonb,0,'An unattended running vehicle can be stolen or roll.','Un vehículo prendido y solo puede ser robado o moverse.','general hospitality best practice',array['driver']::text[],'role','easy',array['idling','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lane','A deer jumps in front of the van. What does MN DPS advise?','Un venado salta frente a la van. ¿Qué aconseja DPS de MN?','["Turn into oncoming traffic", "Swerve into the ditch", "Speed up", "Brake firmly and stay in your lane — don''t swerve"]'::jsonb,'["Irte al carril contrario", "Volantear a la cuneta", "Acelerar", "Frenar firme y quedarte en tu carril; no volantear"]'::jsonb,3,'Swerving often causes worse crashes than hitting the deer.','Volantear causa choques peores que pegarle al venado.','https://dps.mn.gov/divisions/ots',array['driver']::text[],'role','med',array['lane','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','work_zone','In a work zone with workers present, what applies?','En una zona de obras con trabajadores, ¿qué aplica?','["Honk at workers", "Slow down, follow signs, no phone — fines can double", "Normal speed", "Pass on the shoulder"]'::jsonb,'["Pitarles a los trabajadores", "Baja la velocidad, sigue letreros, sin celular; multas pueden duplicarse", "Velocidad normal", "Rebasar por el acotamiento"]'::jsonb,1,'MnDOT work-zone rules.','Reglas de zonas de obra de MnDOT.','https://www.dot.state.mn.us/workzone/',array['driver']::text[],'role','easy',array['work_zone','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','roundabout','Entering a roundabout, who has the right of way?','Al entrar a una glorieta, ¿quién tiene preferencia?','["Trucks only", "Whoever is faster", "You do", "Traffic already in the roundabout"]'::jsonb,'["Solo camiones", "El más rápido", "Tú", "Los que ya están en la glorieta"]'::jsonb,3,'MnDOT: yield to traffic in the roundabout.','MnDOT: cede el paso a quien ya circula.','https://www.dot.state.mn.us/roundabouts/',array['driver']::text[],'role','med',array['roundabout','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','zipper','MnDOT''s ''zipper merge'' for a lane closure means…','El ''zipper merge'' de MnDOT en un cierre de carril significa…','["Speed up to cut in", "Merge as early as possible", "Block the closed lane", "Use both lanes to the merge point, then take turns"]'::jsonb,'["Acelerar para meterse", "Unirse lo antes posible", "Bloquear el carril cerrado", "Usar ambos carriles hasta el punto de unión y turnarse"]'::jsonb,3,'MnDOT promotes the late, alternating zipper merge in heavy traffic.','MnDOT promueve unirse al final y turnarse con tráfico pesado.','https://www.dot.state.mn.us/zippermerge/',array['driver']::text[],'role','med',array['zipper','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','emergency_veh','An ambulance with siren comes up behind you. What do you do?','Una ambulancia con sirena viene atrás. ¿Qué haces?','["Speed up", "Pull to the right and stop until it passes", "Keep going", "Stop in the lane"]'::jsonb,'["Acelerar", "Orillarte a la derecha y parar hasta que pase", "Seguir", "Parar en el carril"]'::jsonb,1,'MN 169.20: yield and pull right for emergency vehicles.','MN 169.20: cede el paso y orillate a la derecha.','https://www.revisor.mn.gov/statutes/cite/169.20',array['driver']::text[],'role','easy',array['emergency_veh','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','right_on_red','Is right turn on red allowed in Minnesota?','¿Se permite vuelta a la derecha en rojo en Minnesota?','["Only at night", "Yes, after a full stop, unless a sign prohibits it", "Never", "Without stopping"]'::jsonb,'["Solo de noche", "Sí, después de alto total, salvo letrero que lo prohíba", "Nunca", "Sin parar"]'::jsonb,1,'MN 169.06 permits right on red after stopping unless posted.','MN 169.06 lo permite tras alto total, salvo letrero.','https://www.revisor.mn.gov/statutes/cite/169.06',array['driver']::text[],'role','med',array['right_on_red','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guests','Should you discuss guest names or room numbers out loud in the van?','¿Debes decir nombres o números de cuarto en voz alta en la van?','["Yes, to be friendly", "No — keep guest info private", "Only room numbers", "Only at night"]'::jsonb,'["Sí, para ser amable", "No; la información del huésped es privada", "Solo el número", "Solo de noche"]'::jsonb,1,'Guest privacy applies in the shuttle too.','La privacidad del huésped aplica en el shuttle también.','general hospitality best practice',array['driver']::text[],'role','easy',array['guests','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guests','A guest leaves a bag in the van. What do you do?','Un huésped deja una bolsa en la van. ¿Qué haces?','["Leave it in the van", "Keep it", "Bring it to the front desk and log it in lost and found", "Open it and use it"]'::jsonb,'["Dejarla en la van", "Quedártela", "Llevarla a recepción y registrarla en objetos perdidos", "Abrirla y usarla"]'::jsonb,2,'Items go to lost and found so the guest can be contacted.','Los objetos van a objetos perdidos para contactar al huésped.','general hospitality best practice',array['driver']::text[],'role','med',array['guests','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tips','A guest asks if the shuttle is free. What do you say (at hotels with a free shuttle)?','Un huésped pregunta si el shuttle es gratis. ¿Qué dices (en hoteles con shuttle gratis)?','["$10 a person", "Ask the airport", "Only for members", "Yes, it''s complimentary"]'::jsonb,'["$10 por persona", "Pregunte en el aeropuerto", "Solo para miembros", "Sí, es gratis"]'::jsonb,3,'Our airport-area hotels list a complimentary shuttle.','Nuestros hoteles del aeropuerto ofrecen shuttle gratis.','general hospitality best practice',array['driver']::text[],'role','easy',array['tips','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','weather','Freezing rain is forecast for your morning runs. What''s smart?','Pronostican lluvia helada para tus viajes de la mañana. ¿Qué es lo mejor?','["Drive faster to beat it", "Check 511 and talk to your manager about timing — leave extra time", "Use cruise control", "Skip the pre-trip"]'::jsonb,'["Manejar más rápido", "Revisar el 511 y hablar con tu gerente; salir con más tiempo", "Usar control de crucero", "Saltarte la revisión"]'::jsonb,1,'MnDOT 511 has road conditions; never use cruise control on ice.','El 511 de MnDOT da condiciones; nunca uses crucero en hielo.','https://511mn.org/',array['driver']::text[],'role','med',array['weather','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','weather','Should you use cruise control on snowy or icy roads?','¿Debes usar control de crucero en nieve o hielo?','["No", "Yes, it''s smoother", "Only at night", "Only uphill"]'::jsonb,'["No", "Sí, es más suave", "Solo de noche", "Solo en subida"]'::jsonb,0,'Cruise control can make you lose control on slippery roads.','El crucero puede hacerte perder el control en caminos resbalosos.','https://www.dot.state.mn.us/workzone/winter.html',array['driver']::text[],'role','easy',array['weather','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','mirrors','When should you adjust your mirrors?','¿Cuándo ajustas los espejos?','["After a crash", "Never", "Before you start driving", "While on the highway"]'::jsonb,'["Después de un choque", "Nunca", "Antes de empezar a manejar", "En la autopista"]'::jsonb,2,'Adjust seat and mirrors before moving.','Ajusta asiento y espejos antes de avanzar.','https://dps.mn.gov/divisions/dvs',array['driver']::text[],'role','easy',array['mirrors','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','blind_spot','How do you check a blind spot before changing lanes?','¿Cómo revisas el punto ciego antes de cambiar de carril?','["Honk first", "Signal, check mirrors, then a quick look over your shoulder", "Just the signal", "Just the mirror"]'::jsonb,'["Pitar primero", "Direccional, espejos y una vista rápida sobre el hombro", "Solo la direccional", "Solo el espejo"]'::jsonb,1,'MN Driver''s Manual: shoulder check before lane changes.','Manual de MN: voltea sobre el hombro antes de cambiar de carril.','https://dps.mn.gov/divisions/dvs',array['driver']::text[],'role','med',array['blind_spot','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','signal','How far ahead must you signal a turn in Minnesota?','¿Con cuánta anticipación debes poner la direccional en MN?','["At least 100 feet", "At the turn", "10 feet", "No need"]'::jsonb,'["Al menos 100 pies", "En la vuelta", "10 pies", "No es necesario"]'::jsonb,0,'MN 169.19: signal at least 100 feet before turning.','MN 169.19: direccional al menos 100 pies antes.','https://www.revisor.mn.gov/statutes/cite/169.19',array['driver']::text[],'role','easy',array['signal','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','loading','How should heavy bags be placed in the shuttle?','¿Cómo se acomodan las maletas pesadas en el shuttle?','["Low, secured, and out of the aisle", "In the aisle", "On the dash", "On the seats stacked high"]'::jsonb,'["Abajo, aseguradas y fuera del pasillo", "En el pasillo", "En el tablero", "En los asientos, apiladas"]'::jsonb,0,'Loose heavy items become projectiles in a sudden stop.','Las maletas sueltas salen volando al frenar.','general hospitality best practice',array['driver']::text[],'role','med',array['loading','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lifting','How do you lift a heavy suitcase into the van safely?','¿Cómo subes una maleta pesada a la van sin lastimarte?','["Twist at the waist", "Bend your knees, keep it close, don''t twist — ask for help if needed", "Throw it in", "Yank it with one arm"]'::jsonb,'["Girar la cintura", "Doblar rodillas, pegarla al cuerpo, sin girar; pedir ayuda si hace falta", "Aventarla", "Jalarla con un brazo"]'::jsonb,1,'OSHA safe-lifting basics.','Bases de levantamiento seguro de OSHA.','https://www.osha.gov/ergonomics',array['driver']::text[],'role','med',array['lifting','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','parking','Where should you never stop the shuttle to drop guests?','¿Dónde nunca debes parar el shuttle para bajar huéspedes?','["At the airport shuttle area", "At the hotel entrance", "In a fire lane or crosswalk", "In a marked loading zone"]'::jsonb,'["En la zona de shuttles", "En la entrada del hotel", "En carril de bomberos o paso peatonal", "En zona de carga marcada"]'::jsonb,2,'Fire lanes and crosswalks must be kept clear.','Los carriles de bomberos y cruces deben estar libres.','general hospitality best practice',array['driver']::text[],'role','easy',array['parking','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','child','A family wants their 3-year-old to ride on a lap in the shuttle. What''s the rule in MN?','Una familia quiere llevar a su niño de 3 años en las piernas. ¿Qué dice la ley de MN?','["Laps are fine", "Kids under 8 and under 4''9\" must be in a proper child restraint", "No rule", "Only on the highway"]'::jsonb,'["En las piernas está bien", "Los menores de 8 años y de menos de 4''9\" deben ir en asiento infantil", "No hay regla", "Solo en autopista"]'::jsonb,1,'MN 169.685: child passenger restraints.','MN 169.685: sistemas de retención infantil.','https://www.revisor.mn.gov/statutes/cite/169.685',array['driver']::text[],'role','hard',array['child','driver']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','When should the dryer lint screen be cleaned?','¿Cuándo se limpia el filtro de pelusa de la secadora?','["Once a month", "Once a week", "When it catches fire", "Before or after every load"]'::jsonb,'["Una vez al mes", "Una vez a la semana", "Cuando se incendie", "Antes o después de cada carga"]'::jsonb,3,'USFA: clean the lint filter every load — lint buildup is a leading cause of dryer fires.','USFA: limpia el filtro en cada carga; la pelusa causa muchos incendios.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','easy',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','Why shouldn''t oily rags (from kitchen or maintenance) be dried and left piled warm?','¿Por qué no se deben dejar amontonados y calientes trapos con aceite?','["They lose color", "They smell", "They shrink", "They can heat up and catch fire on their own"]'::jsonb,'["Se destiñen", "Huelen", "Se encogen", "Se pueden calentar e incendiar solos"]'::jsonb,3,'Oil-soaked fabric can self-heat after drying; cool-down cycles and spreading out prevent fires.','La tela con aceite puede calentarse sola; enfriar y extender evita incendios.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','med',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','Why use the cool-down cycle at the end of drying?','¿Para qué sirve el ciclo de enfriamiento al final del secado?','["It''s just to save time", "It sanitizes", "It adds softener", "It lowers heat to prevent fires and wrinkles"]'::jsonb,'["Solo ahorra tiempo", "Desinfecta", "Agrega suavizante", "Baja el calor para evitar incendios y arrugas"]'::jsonb,3,'Hot piled linen holds heat; cool-down reduces fire risk.','La ropa caliente amontonada guarda calor; enfriar reduce el riesgo.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','med',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dryer','What should you do if a dryer smells like burning?','¿Qué haces si una secadora huele a quemado?','["Keep running it", "Spray water inside", "Stop it, keep the door closed if smoking, and tell your supervisor", "Open it and grab the linen"]'::jsonb,'["Dejarla funcionando", "Echarle agua", "Apagarla, dejar la puerta cerrada si sale humo y avisar al supervisor", "Abrirla y sacar la ropa"]'::jsonb,2,'Report immediately; don''t open a smoldering dryer — it feeds the fire oxygen.','Reporta de inmediato; no abras una secadora con humo, le da oxígeno.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','easy',array['dryer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','washer','What''s the danger of overloading a washer?','¿Qué pasa si sobrecargas la lavadora?','["Linen doesn''t get clean or rinsed and the machine wears out", "Nothing", "It saves water and works great", "It cleans better"]'::jsonb,'["La ropa no se lava ni enjuaga bien y la máquina se desgasta", "Nada", "Ahorra agua y funciona perfecto", "Lava mejor"]'::jsonb,0,'Follow the machine''s rated load weight.','Respeta el peso de carga de la máquina.','general hospitality best practice',array['laundry']::text[],'role','easy',array['washer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','washer','Where do you find a washer''s rated load capacity?','¿Dónde encuentras la capacidad de carga de la lavadora?','["On the machine''s plate or manual (in pounds)", "Guess by eye", "On the detergent box", "On the linen tag"]'::jsonb,'["En la placa o manual de la máquina (en libras)", "Al tanteo", "En la caja de detergente", "En la etiqueta de la ropa"]'::jsonb,0,'Commercial washers are rated by dry weight.','Las lavadoras comerciales se miden por peso seco.','general hospitality best practice',array['laundry']::text[],'role','med',array['washer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','washer','Why weigh or count a load instead of ''stuffing it full''?','¿Por qué pesar o contar la carga en lugar de ''llenarla''?','["Consistent loads get the right chemical dose and clean evenly", "It''s slower", "It uses more water", "No reason"]'::jsonb,'["Cargas parejas reciben la dosis correcta y se lavan igual", "Es más lento", "Gasta más agua", "Por nada"]'::jsonb,0,'Dosing systems assume a set load weight.','Los dosificadores asumen un peso fijo.','general hospitality best practice',array['laundry']::text[],'role','hard',array['washer','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lockout','A washer jams mid-cycle. Can you reach in while it''s powered?','Una lavadora se atora a medio ciclo. ¿Puedes meter la mano estando prendida?','["No — stop it, wait, and call maintenance; follow lockout rules", "Yes, quickly", "Only if it''s slow", "Yes, with gloves"]'::jsonb,'["No; apágala, espera y llama a mantenimiento; sigue el bloqueo", "Sí, rápido", "Solo si va lento", "Sí, con guantes"]'::jsonb,0,'OSHA lockout/tagout protects workers from machines starting.','El bloqueo/etiquetado de OSHA protege de arranques.','https://www.osha.gov/control-hazardous-energy',array['laundry']::text[],'role','med',array['lockout','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lockout','A machine has a ''Do Not Operate'' tag on it. What do you do?','Una máquina tiene etiqueta ''No operar''. ¿Qué haces?','["Throw the tag away", "Remove the tag and use it", "Use it carefully", "Leave it off — only the person who tagged it removes the tag"]'::jsonb,'["Tirar la etiqueta", "Quitar la etiqueta y usarla", "Usarla con cuidado", "No usarla; solo quien la etiquetó quita la etiqueta"]'::jsonb,3,'OSHA: tags are removed only by the authorized person.','OSHA: solo la persona autorizada quita la etiqueta.','https://www.osha.gov/control-hazardous-energy',array['laundry']::text[],'role','easy',array['lockout','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','The auto-dispense detergent pump is leaking. What''s safest?','La bomba de detergente automático gotea. ¿Qué es lo más seguro?','["Wipe with bare hands", "Mix in bleach to clean it", "Ignore it", "Wear gloves/goggles per the SDS, contain it, and report it"]'::jsonb,'["Limpiar con la mano", "Mezclar con cloro", "Ignorarlo", "Usar guantes y lentes según la SDS, contener y reportar"]'::jsonb,3,'Laundry chemicals can be caustic; follow SDS PPE.','Los químicos de lavandería pueden ser corrosivos; usa el EPP de la SDS.','https://www.osha.gov/hazcom',array['laundry']::text[],'role','med',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Laundry chemical splashes in your eye. First thing?','Te salpica químico de lavandería en el ojo. ¿Primero qué?','["Rub it", "Flush with water at the eyewash for at least 15 minutes", "Use a towel only", "Wait"]'::jsonb,'["Tallarlo", "Enjuagar en el lavaojos al menos 15 minutos", "Solo una toalla", "Esperar"]'::jsonb,1,'OSHA/SDS first aid: flush eyes 15+ minutes.','Primeros auxilios: enjuaga 15 minutos o más.','https://www.osha.gov/medical-first-aid',array['laundry']::text[],'role','easy',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','Why is bleach not used on every load?','¿Por qué no se usa cloro en todas las cargas?','["It''s illegal", "It makes linen dirtier", "It''s too cheap", "It can weaken fibers and damage colors — use it only where the program calls for it"]'::jsonb,'["Es ilegal", "Ensucia más", "Es muy barato", "Debilita fibras y daña colores; solo donde el programa lo indique"]'::jsonb,3,'Follow the chemical program and fabric care labels.','Sigue el programa de químicos y las etiquetas.','https://www.ftc.gov/business-guidance/resources/clothes-captions-complying-care-labeling-rule',array['laundry']::text[],'role','med',array['chemicals','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ppe','What PPE do you wear when sorting soiled linen?','¿Qué EPP usas al separar ropa sucia?','["Sunglasses", "Only an apron", "None", "Gloves (and more if there''s blood or fluids)"]'::jsonb,'["Lentes de sol", "Solo mandil", "Nada", "Guantes (y más si hay sangre o fluidos)"]'::jsonb,3,'OSHA bloodborne pathogens: gloves for contaminated laundry.','OSHA: guantes para ropa contaminada.','https://www.osha.gov/bloodborne-pathogens',array['laundry']::text[],'role','easy',array['ppe','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','soiled','How should linen with blood on it be handled?','¿Cómo se maneja la ropa con sangre?','["Bag it separately with minimal handling, wearing gloves", "Mix it with clean linen", "Rinse it in a sink with bare hands", "Shake it out first"]'::jsonb,'["Embolsarla aparte con mínimo manejo y con guantes", "Mezclarla con ropa limpia", "Enjuagarla a mano sin guantes", "Sacudirla primero"]'::jsonb,0,'OSHA: handle contaminated laundry as little as possible; don''t sort or rinse where used.','OSHA: manipula lo menos posible; no separes ni enjuagues en el lugar.','https://www.osha.gov/bloodborne-pathogens',array['laundry']::text[],'role','med',array['soiled','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','soiled','Why not shake dirty linen?','¿Por qué no se sacude la ropa sucia?','["It tears", "It spreads germs and dust into the air", "It''s slow", "It wrinkles"]'::jsonb,'["Se rompe", "Esparce gérmenes y polvo al aire", "Es lento", "Se arruga"]'::jsonb,1,'CDC: avoid shaking soiled linen.','CDC: evita sacudir la ropa sucia.','https://www.cdc.gov/infection-control/hcp/environmental-control/laundry-bedding.html',array['laundry']::text[],'role','easy',array['soiled','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sorting','Before washing, what should you check pockets and linen for?','Antes de lavar, ¿qué buscas en la ropa?','["Nothing", "Sharp objects, pens, and guest items", "Only colors", "Only stains"]'::jsonb,'["Nada", "Objetos filosos, plumas y cosas del huésped", "Solo colores", "Solo manchas"]'::jsonb,1,'Needles, pens and phones can hurt you or ruin a whole load.','Agujas, plumas y celulares lastiman o arruinan la carga.','general hospitality best practice',array['laundry']::text[],'role','easy',array['sorting','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','sorting','You find a guest''s ring in the sheets. What do you do?','Encuentras un anillo de un huésped en las sábanas. ¿Qué haces?','["Give it to your supervisor for lost and found with the room/date if known", "Keep it", "Sell it", "Leave it in the linen"]'::jsonb,'["Darlo al supervisor para objetos perdidos con cuarto y fecha si se sabe", "Quedártelo", "Venderlo", "Dejarlo en la ropa"]'::jsonb,0,'Lost items are logged so the guest can be contacted.','Se registran para contactar al huésped.','general hospitality best practice',array['laundry']::text[],'role','med',array['sorting','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stains','A white towel has makeup stains. What''s best?','Una toalla blanca tiene manchas de maquillaje. ¿Qué es lo mejor?','["Pre-treat/send to the reclaim (stain) process before the regular wash", "Dry it on high", "Throw it out right away", "Wash it normally and hope"]'::jsonb,'["Pretratar o mandar a recuperación de manchas antes del lavado normal", "Secarla en alto", "Tirarla", "Lavarla normal"]'::jsonb,0,'Heat sets stains; treat before drying.','El calor fija las manchas; trata antes de secar.','general hospitality best practice',array['laundry']::text[],'role','med',array['stains','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stains','Why not dry a stained item before it''s treated?','¿Por qué no secar algo manchado antes de tratarlo?','["No reason", "It dries faster", "It''s the rule for colors only", "Dryer heat can set the stain permanently"]'::jsonb,'["Por nada", "Se seca más rápido", "Solo para colores", "El calor de la secadora puede fijar la mancha"]'::jsonb,3,'Heat sets most protein and oil stains.','El calor fija manchas de proteína y grasa.','general hospitality best practice',array['laundry']::text[],'role','easy',array['stains','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','rags','A torn or permanently stained towel should be…','Una toalla rota o con mancha permanente se debe…','["Folded and sent to a room", "Put back in the wash forever", "Hidden", "Pulled from service (rag-out) and recorded"]'::jsonb,'["Doblar y mandar al cuarto", "Lavar para siempre", "Esconder", "Retirar (a trapos) y registrar"]'::jsonb,3,'Guests should never get damaged linen; tracking helps ordering.','El huésped nunca debe recibir ropa dañada; registrar ayuda a pedir.','general hospitality best practice',array['laundry']::text[],'role','easy',array['rags','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','folding','Why fold linen right after the dryer?','¿Por qué doblar la ropa justo al salir de la secadora?','["Fewer wrinkles and a better look", "It''s faster to leave it", "Doesn''t matter", "It''s warmer for you"]'::jsonb,'["Menos arrugas y mejor presentación", "Dejarla es más rápido", "No importa", "Está calientita"]'::jsonb,0,'Linen left in a pile wrinkles and holds heat.','La ropa amontonada se arruga y guarda calor.','general hospitality best practice',array['laundry']::text[],'role','easy',array['folding','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','folding','What should a folded towel stack look like for a cart?','¿Cómo debe verse una pila de toallas para el carro?','["Same fold, edges facing the same way, neat stacks", "Mixed sizes", "Rolled tight", "Any fold"]'::jsonb,'["Mismo doblez, orillas al mismo lado, pilas parejas", "Tamaños mezclados", "Enrollada", "Cualquier doblez"]'::jsonb,0,'Consistent folds speed up room setup and look professional.','Un doblez uniforme ahorra tiempo y se ve profesional.','general hospitality best practice',array['laundry']::text[],'role','med',array['folding','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','par','What does linen ''par'' mean?','¿Qué significa ''par'' de blancos?','["A price", "A golf term only", "The number of complete sets per bed needed to run the hotel", "Linen thrown out"]'::jsonb,'["Un precio", "Solo término de golf", "Cuántos juegos completos por cama se necesitan para operar", "Ropa tirada"]'::jsonb,2,'Hotels often run about 3–4 par: one on the bed, one in laundry, one on the shelf, spare.','Se manejan 3–4 juegos: en la cama, en lavandería, en el estante y repuesto.','general hospitality best practice',array['laundry']::text[],'role','med',array['par','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','par','Why does running low on linen par hurt the hotel?','¿Por qué afecta quedarse bajo de juegos de blancos?','["It makes linen softer", "Linen gets rushed and worn faster and rooms can''t be finished", "It saves money", "Nothing happens"]'::jsonb,'["La suaviza", "Se apresura y desgasta más la ropa y no se terminan cuartos", "Ahorra dinero", "No pasa nada"]'::jsonb,1,'Linen needs rest time between uses; low par causes delays.','La ropa necesita descanso entre usos; poco par causa retrasos.','general hospitality best practice',array['laundry']::text[],'role','hard',array['par','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','carts','Clean linen is being moved through the building. How should it be covered?','Se mueve ropa limpia por el hotel. ¿Cómo se cubre?','["Covered or in a closed cart", "It doesn''t need covering", "On the floor", "Wrapped in dirty sheets"]'::jsonb,'["Tapada o en carro cerrado", "No hace falta", "En el piso", "Envuelta en sábanas sucias"]'::jsonb,0,'CDC: protect clean linen from contamination in transport.','CDC: protege la ropa limpia al transportarla.','https://www.cdc.gov/infection-control/hcp/environmental-control/laundry-bedding.html',array['laundry']::text[],'role','med',array['carts','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','floor','Clean linen falls on the floor. What do you do?','Se cae ropa limpia al piso. ¿Qué haces?','["Use it for the GM only", "Shake it off", "Fold it anyway", "Rewash it"]'::jsonb,'["Solo para el gerente", "Sacudirla", "Doblarla igual", "Volver a lavarla"]'::jsonb,3,'Floor contact contaminates clean linen.','El piso contamina la ropa limpia.','https://www.cdc.gov/infection-control/hcp/environmental-control/laundry-bedding.html',array['laundry']::text[],'role','easy',array['floor','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','heat','The laundry room is very hot in summer. What helps?','La lavandería está muy caliente en verano. ¿Qué ayuda?','["Work through it", "Wear more layers", "Drink water often, take breaks, and tell your supervisor if you feel sick", "Drink only soda"]'::jsonb,'["Aguantarte", "Más ropa", "Tomar agua seguido, descansar y avisar si te sientes mal", "Solo refresco"]'::jsonb,2,'OSHA heat guidance: water, rest, shade.','OSHA: agua, descanso, sombra.','https://www.osha.gov/heat-exposure',array['laundry']::text[],'role','med',array['heat','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','How can you reduce strain pulling wet linen from a washer?','¿Cómo reduces el esfuerzo al sacar ropa mojada de la lavadora?','["Twist and throw", "Pull smaller amounts, keep it close, and avoid twisting", "Use one arm", "Pull it all at once"]'::jsonb,'["Girar y aventar", "Sacar menos a la vez, pegada al cuerpo, sin girar", "Un solo brazo", "Toda de un jalón"]'::jsonb,1,'OSHA ergonomics for laundry.','Ergonomía OSHA en lavandería.','https://www.osha.gov/ergonomics',array['laundry']::text[],'role','med',array['ergonomics','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ergonomics','Wet linen is how much heavier than dry?','¿Cuánto más pesa la ropa mojada que seca?','["Lighter", "Slightly lighter", "Much heavier — often 2 or more times", "The same"]'::jsonb,'["Más ligera", "Un poco más ligera", "Mucho más; a veces el doble o más", "Igual"]'::jsonb,2,'Water weight adds up fast; lift smart.','El agua pesa; levanta con cuidado.','https://www.osha.gov/ergonomics',array['laundry']::text[],'role','easy',array['ergonomics','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','floor','Water on the laundry floor near machines. What first?','Hay agua en el piso junto a las máquinas. ¿Primero qué?','["Cover with towels and leave", "Wet-floor sign, then mop and report any leak", "Ignore", "Walk fast"]'::jsonb,'["Tapar con toallas e irte", "Señal de piso mojado, trapear y reportar la fuga", "Ignorar", "Caminar rápido"]'::jsonb,1,'OSHA walking-working surfaces.','OSHA superficies.','https://www.osha.gov/walking-working-surfaces',array['laundry']::text[],'role','easy',array['floor','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pillows','How should pillows and comforters be washed?','¿Cómo se lavan almohadas y edredones?','["Hot and high with bleach always", "Never", "Per the care label, on the right cycle, and fully dried to avoid mildew", "By hand only"]'::jsonb,'["Siempre caliente y con cloro", "Nunca", "Según la etiqueta, en el ciclo correcto y bien secos para evitar moho", "Solo a mano"]'::jsonb,2,'FTC care labels give the right method.','Las etiquetas de cuidado indican el método.','https://www.ftc.gov/business-guidance/resources/clothes-captions-complying-care-labeling-rule',array['laundry']::text[],'role','med',array['pillows','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','care_label','What does a tub symbol with one dot mean on a care label?','¿Qué significa una tina con un punto en la etiqueta?','["Do not wash", "Wash cold", "Wash hot", "Dry clean only"]'::jsonb,'["No lavar", "Lavar en frío", "Lavar caliente", "Solo en seco"]'::jsonb,1,'Care symbols: more dots = hotter water; one dot is cold.','Más puntos = más caliente; un punto es frío.','https://www.ftc.gov/business-guidance/resources/clothes-captions-complying-care-labeling-rule',array['laundry']::text[],'role','easy',array['care_label','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','care_label','A triangle with an X on a care label means…','Un triángulo con X en la etiqueta significa…','["Bleach only", "Iron", "Do not bleach", "Dry clean"]'::jsonb,'["Solo cloro", "Planchar", "No usar cloro", "Lavado en seco"]'::jsonb,2,'Triangle = bleach; crossed out = no bleach.','Triángulo = cloro; tachado = no cloro.','https://www.ftc.gov/business-guidance/resources/clothes-captions-complying-care-labeling-rule',array['laundry']::text[],'role','med',array['care_label','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','mildew','Damp linen left in a cart overnight can…','Ropa húmeda en un carro toda la noche puede…','["Grow mildew and smell", "Nothing", "Get cleaner", "Get softer"]'::jsonb,'["Hacer moho y oler", "Nada", "Quedar más limpia", "Más suave"]'::jsonb,0,'Wet linen should go to dry promptly.','La ropa mojada debe secarse pronto.','general hospitality best practice',array['laundry']::text[],'role','easy',array['mildew','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','energy','Why not run a dryer half empty?','¿Por qué no usar la secadora medio vacía?','["It''s required", "It protects the drum", "It wastes energy and gas", "It dries better"]'::jsonb,'["Es obligatorio", "Protege el tambor", "Gasta energía y gas", "Seca mejor"]'::jsonb,2,'Full (not over-full) loads use energy best.','Cargas completas (no de más) aprovechan energía.','general hospitality best practice',array['laundry']::text[],'role','med',array['energy','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','guest_items','A guest''s own clothes come down to laundry with hotel linen. What do you do?','Ropa del huésped baja a lavandería con la del hotel. ¿Qué haces?','["Wash it with hotel linen", "Keep it separate and give it to your supervisor", "Throw it away", "Keep it"]'::jsonb,'["Lavarla con la del hotel", "Apartarla y dársela al supervisor", "Tirarla", "Quedártela"]'::jsonb,1,'Guest property is lost and found.','Lo del huésped va a objetos perdidos.','general hospitality best practice',array['laundry']::text[],'role','med',array['guest_items','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lint','Besides the lint screen, what other dryer area builds up lint and needs regular service?','Aparte del filtro, ¿qué parte de la secadora junta pelusa y necesita servicio?','["The exhaust duct/vent", "The door glass", "The control panel", "The drum paint"]'::jsonb,'["El ducto de escape", "El vidrio de la puerta", "El tablero", "La pintura del tambor"]'::jsonb,0,'USFA: clean the vent and exhaust duct regularly.','USFA: limpia el ducto con regularidad.','https://www.usfa.fema.gov/prevention/home-fires/prevent-fires/clothes-dryers/',array['laundry']::text[],'role','hard',array['lint','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','schedule','Why wash in the order your supervisor sets (e.g., sheets first)?','¿Por qué lavar en el orden del supervisor (por ejemplo sábanas primero)?','["Machines need it", "For fun", "Rooms need specific items first so housekeeping isn''t waiting", "It''s random"]'::jsonb,'["Las máquinas lo piden", "Por gusto", "Los cuartos necesitan ciertas piezas primero para no esperar", "Es al azar"]'::jsonb,2,'Priorities keep room attendants supplied.','Las prioridades abastecen a las recamareras.','general hospitality best practice',array['laundry']::text[],'role','easy',array['schedule','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','tools','Why keep the laundry door closed and the room organized?','¿Por qué mantener la puerta cerrada y la lavandería ordenada?','["It looks nicer only", "Security, fire safety and fewer trips and slips", "To hide work", "No reason"]'::jsonb,'["Solo se ve mejor", "Seguridad, prevención de incendios y menos tropiezos", "Para esconder el trabajo", "Por nada"]'::jsonb,1,'Clutter and lint are fire and trip hazards.','El desorden y la pelusa son riesgo de incendio y tropiezos.','https://www.osha.gov/walking-working-surfaces',array['laundry']::text[],'role','med',array['tools','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','towels','New towels sometimes leave lint. Why wash new linen before use?','Las toallas nuevas sueltan pelusa. ¿Por qué lavarlas antes de usarlas?','["To shrink them", "They''re dirty from guests", "To remove finishes and lint so they absorb well", "It''s not needed"]'::jsonb,'["Para encogerlas", "Están sucias de huéspedes", "Para quitar acabados y pelusa y que absorban", "No hace falta"]'::jsonb,2,'New linen has sizing that reduces absorbency.','La ropa nueva trae apresto que reduce la absorción.','general hospitality best practice',array['laundry']::text[],'role','med',array['towels','laundry']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bedbugs','What are signs of bed bugs when stripping a bed?','¿Qué señales de chinches ves al quitar la cama?','["A sweet smell only", "Big holes", "White powder", "Small dark spots, shed skins, or tiny live bugs on seams"]'::jsonb,'["Solo olor dulce", "Hoyos grandes", "Polvo blanco", "Puntitos oscuros, mudas o bichitos en las costuras"]'::jsonb,3,'EPA: look for dark spots, eggs, shed skins and live bugs on mattress seams.','EPA: busca manchitas, huevos, mudas y bichos en costuras.','https://www.epa.gov/bedbugs',array['hk_supervisor','room_attendant']::text[],'role','med',array['bedbugs','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','bedbugs','You think you see bed bugs. What do you do?','Crees ver chinches. ¿Qué haces?','["Spray anything you have", "Keep cleaning", "Stop, don''t move linen to other rooms, and tell your supervisor", "Take the linen to the next room"]'::jsonb,'["Rociar lo que tengas", "Seguir limpiando", "Parar, no mover la ropa a otros cuartos y avisar al supervisor", "Llevar la ropa al siguiente cuarto"]'::jsonb,2,'Containing the room prevents spreading; professionals treat it.','Aislar el cuarto evita que se propague; tratan profesionales.','https://www.epa.gov/bedbugs',array['hk_supervisor','room_attendant']::text[],'role','easy',array['bedbugs','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','disinfect','What''s ''dwell time'' on a disinfectant label?','¿Qué es el ''tiempo de contacto'' en la etiqueta del desinfectante?','["Time to smell", "How long the surface must stay wet to kill germs", "How long it lasts in the bottle", "Drying time of the floor"]'::jsonb,'["Tiempo del olor", "Cuánto debe quedarse mojada la superficie para matar gérmenes", "Cuánto dura en la botella", "Tiempo de secado del piso"]'::jsonb,1,'EPA/CDC: follow label contact time.','EPA/CDC: sigue el tiempo de contacto.','https://www.epa.gov/pesticide-registration/selected-epa-registered-disinfectants',array['hk_supervisor','room_attendant']::text[],'role','med',array['disinfect','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','disinfect','Clean first, then disinfect. Why?','Primero limpiar y luego desinfectar. ¿Por qué?','["Disinfectant cleans dirt", "No reason", "It''s faster the other way", "Dirt blocks disinfectant from working"]'::jsonb,'["El desinfectante limpia", "Por nada", "Al revés es más rápido", "La suciedad impide que el desinfectante funcione"]'::jsonb,3,'CDC: cleaning removes soil so disinfecting works.','CDC: limpiar quita suciedad para que desinfectar funcione.','https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-a-facility.html',array['hk_supervisor','room_attendant']::text[],'role','easy',array['disinfect','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','disinfect','Which surfaces are ''high-touch'' in a guest room?','¿Cuáles son superficies de mucho contacto en un cuarto?','["Ceiling", "Behind the dresser", "Remote, light switches, door handles, phone, faucet", "Window glass top"]'::jsonb,'["Techo", "Detrás del mueble", "Control, apagadores, manijas, teléfono, llave del agua", "Parte alta de la ventana"]'::jsonb,2,'CDC: prioritize high-touch surfaces.','CDC: prioriza superficies de mucho contacto.','https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-a-facility.html',array['hk_supervisor','room_attendant']::text[],'role','med',array['disinfect','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','glasses','How should drinking glasses be handled in a room?','¿Cómo se manejan los vasos del cuarto?','["Rinse in the bathroom sink", "Replace with clean, sanitized ones from the supply area — never wash in the bathroom sink", "Leave as is", "Wipe with the towel"]'::jsonb,'["Enjuagar en el lavabo", "Cambiarlos por limpios y sanitizados del almacén; nunca lavarlos en el lavabo", "Dejarlos igual", "Secar con la toalla"]'::jsonb,1,'Glasses washed in-room are a known health risk.','Lavar vasos en el cuarto es riesgo de salud.','https://www.cdc.gov/hygiene/about/when-and-how-to-clean-and-disinfect-a-facility.html',array['hk_supervisor','room_attendant']::text[],'role','med',array['glasses','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','order','What order makes cleaning a room efficient?','¿Qué orden hace eficiente limpiar un cuarto?','["Top to bottom, dry to wet, back to front", "Random", "Bathroom last only", "Floor first"]'::jsonb,'["De arriba a abajo, seco a mojado, de atrás hacia la puerta", "Al azar", "Solo el baño al final", "Primero el piso"]'::jsonb,0,'Dust falls down; finish at the door.','El polvo cae; terminas en la puerta.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['order','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','dnd','A room has had ''Do Not Disturb'' for days. What''s right?','Un cuarto tiene ''No molestar'' desde hace días. ¿Qué es lo correcto?','["Slide a note and leave it", "Knock and enter", "Report it to your supervisor for a welfare check per policy", "Ignore it forever"]'::jsonb,'["Dejar nota y ya", "Tocar y entrar", "Reportarlo al supervisor para revisión de bienestar según la política", "Ignorarlo"]'::jsonb,2,'Long DND can mean a guest in trouble; policy sets when to check.','Un ''No molestar'' largo puede significar un problema.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['dnd','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','entry','How do you enter an occupied room?','¿Cómo entras a un cuarto ocupado?','["Walk right in", "Use the phone first only", "Knock, announce ''Housekeeping'', wait, repeat, then enter slowly", "Knock once and enter"]'::jsonb,'["Entrar directo", "Solo llamar", "Tocar, decir ''Housekeeping'', esperar, repetir y entrar despacio", "Tocar una vez y entrar"]'::jsonb,2,'Standard knock-and-announce protects privacy.','Tocar y anunciar protege la privacidad.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['entry','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','entry','You enter and the guest is inside. What do you do?','Entras y el huésped está adentro. ¿Qué haces?','["Clean around them", "Start the bathroom", "Apologize, offer to come back later, and leave", "Ask them to leave"]'::jsonb,'["Limpiar a su alrededor", "Empezar el baño", "Disculparte, ofrecer volver y salir", "Pedirle que salga"]'::jsonb,2,'Respect privacy; return at their preferred time.','Respeta la privacidad; vuelve cuando quiera.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['entry','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cart','Where should your cart be while you clean a room?','¿Dónde va tu carro mientras limpias?','["Inside the bathroom", "Down the hall", "Blocking the open door, with supplies facing the room", "At the elevator"]'::jsonb,'["En el baño", "Al fondo del pasillo", "Tapando la puerta abierta, con suministros hacia el cuarto", "En el elevador"]'::jsonb,2,'The cart secures the door and your supplies.','El carro protege la puerta y tus cosas.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['cart','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','cart','What should never be left unattended on your cart?','¿Qué nunca se deja solo en el carro?','["Master keys and chemicals", "Clean towels", "Notepad", "Toilet paper"]'::jsonb,'["Llaves maestras y químicos", "Toallas limpias", "Libreta", "Papel de baño"]'::jsonb,0,'Keys and chemicals are security and safety risks.','Las llaves y químicos son riesgo.','https://www.osha.gov/hazcom',array['hk_supervisor','room_attendant']::text[],'role','med',array['cart','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','inspection','What do inspectors most often find missed?','¿Qué es lo que más se pasa en las inspecciones?','["Window frames outside", "Hair in the bathroom, dust on tops, and items under the bed", "The hallway", "Ceiling paint"]'::jsonb,'["Marcos exteriores", "Cabellos en el baño, polvo arriba y cosas bajo la cama", "El pasillo", "Pintura del techo"]'::jsonb,1,'Focus spots for a guest-ready room.','Puntos clave para un cuarto listo.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['inspection','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','amenities','A guest asks for more coffee and towels. You''re busy. Best answer?','Un huésped pide café y toallas. Estás ocupada. ¿Mejor respuesta?','["Say no", "Tell them tomorrow", "Get them now or tell the desk/houseman right away", "Ignore"]'::jsonb,'["Decir que no", "Decir que mañana", "Llevarlos ahora o avisar a recepción o al houseman", "Ignorar"]'::jsonb,2,'Quick follow-through earns trust.','Cumplir rápido gana confianza.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['amenities','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','maintenance','You see a dripping faucet in a room. What do you do?','Ves una llave goteando. ¿Qué haces?','["Report it in the maintenance log or to your supervisor", "Turn off the water main", "Fix it with tape", "Ignore it"]'::jsonb,'["Reportarlo en la bitácora o al supervisor", "Cerrar la llave general", "Ponerle cinta", "Ignorarlo"]'::jsonb,0,'Small issues become bigger if not reported.','Lo pequeño crece si no se reporta.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['maintenance','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','mold','You find black spots on the bathroom caulk. What do you do?','Ves manchas negras en el sellador del baño. ¿Qué haces?','["Ignore it", "Paint over it", "Use bleach and ammonia", "Clean per procedure and report if it returns so maintenance can recaulk"]'::jsonb,'["Ignorarlo", "Pintarle encima", "Mezclar cloro y amoníaco", "Limpiar según el procedimiento y reportar si regresa para resellar"]'::jsonb,3,'EPA: clean mold and fix moisture; never mix chemicals.','EPA: limpia el moho y arregla la humedad; nunca mezcles químicos.','https://www.epa.gov/mold',array['hk_supervisor','room_attendant']::text[],'role','med',array['mold','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','checkout','On a checkout, what should you check before stripping the bed?','En una salida, ¿qué revisas antes de quitar la cama?','["For guest items left behind", "Nothing", "The window locks only", "For the TV channels"]'::jsonb,'["Si el huésped dejó cosas", "Nada", "Solo seguros", "Los canales"]'::jsonb,0,'Check drawers, safe, bathroom and bedding for items.','Revisa cajones, caja fuerte, baño y cama.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','easy',array['checkout','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','safe','The in-room safe is locked on a checkout. What do you do?','La caja fuerte está cerrada en una salida. ¿Qué haces?','["Ask a guest", "Force it", "Report it to the supervisor/front desk — don''t try to open it", "Leave it"]'::jsonb,'["Preguntar a un huésped", "Forzarla", "Reportarlo al supervisor o recepción; no intentes abrirla", "Dejarla"]'::jsonb,2,'Locked safes may hold guest valuables; follow the opening procedure.','Puede tener valores; se sigue el procedimiento.','general hospitality best practice',array['hk_supervisor','room_attendant']::text[],'role','med',array['safe','housekeeping']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','Where should a full trash bag from the floor go?','¿A dónde va una bolsa de basura llena del piso?','["Stairwell", "Straight to the dumpster/trash room — not left in a hallway", "Elevator", "Behind a door"]'::jsonb,'["Escalera", "Directo al contenedor o cuarto de basura, no en el pasillo", "Elevador", "Detrás de una puerta"]'::jsonb,1,'Hallways and stairwells must stay clear.','Pasillos y escaleras deben estar libres.','https://www.osha.gov/exit-routes',array['houseman']::text[],'role','easy',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','trash','Why not push down on trash with your hand?','¿Por qué no aplastar la basura con la mano?','["It''s slow", "It smells", "It breaks the bag", "Hidden needles or glass can cut you"]'::jsonb,'["Es lento", "Huele", "Rompe la bolsa", "Agujas o vidrios escondidos te pueden cortar"]'::jsonb,3,'OSHA bloodborne pathogens: hidden sharps.','OSHA: punzocortantes escondidos.','https://www.osha.gov/bloodborne-pathogens',array['houseman']::text[],'role','med',array['trash','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','vacuum','What should you check before vacuuming the hallway?','¿Qué revisas antes de aspirar el pasillo?','["Bag smell", "Cord condition and keep the cord out of walkways", "Only the color", "Nothing"]'::jsonb,'["El olor", "El cable y que no quede en el paso", "Solo el color", "Nada"]'::jsonb,1,'Damaged cords shock; loose cords trip.','Un cable dañado da toques; uno suelto hace tropezar.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role','easy',array['vacuum','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','vacuum','When is a good time to vacuum public hallways?','¿Cuándo conviene aspirar pasillos públicos?','["Midnight", "During check-in rush", "When guest traffic is low and not early morning near rooms", "6 a.m. outside rooms"]'::jsonb,'["A medianoche", "En la hora de llegadas", "Con poco tráfico y no muy temprano junto a cuartos", "6 a. m. fuera de cuartos"]'::jsonb,2,'Noise and cords affect guests.','El ruido y los cables afectan al huésped.','general hospitality best practice',array['houseman']::text[],'role','med',array['vacuum','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','lobby','What''s the first impression area you keep spotless?','¿Qué área de primera impresión mantienes impecable?','["Back dock", "Entrance, lobby and public restrooms", "Roof", "Boiler room"]'::jsonb,'["Muelle", "Entrada, lobby y baños públicos", "Techo", "Calderas"]'::jsonb,1,'Guests judge the hotel in the first minute.','El huésped juzga en el primer minuto.','general hospitality best practice',array['houseman']::text[],'role','easy',array['lobby','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','restroom','How often should lobby restrooms be checked?','¿Cada cuánto se revisan los baños del lobby?','["Regularly through the shift per the checklist (often hourly)", "Only on complaints", "Never", "Once a week"]'::jsonb,'["Seguido durante el turno según la lista (a menudo cada hora)", "Solo con quejas", "Nunca", "Una vez por semana"]'::jsonb,0,'A posted check log is standard.','Una bitácora de revisión es lo común.','general hospitality best practice',array['houseman']::text[],'role','med',array['restroom','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','entrance','In winter, what''s the main entrance hazard to manage?','En invierno, ¿qué peligro hay en la entrada?','["Wet floors from snow — mats, signs and mopping", "Dust", "Too much sun", "Noise"]'::jsonb,'["Piso mojado por nieve: tapetes, señales y trapear", "Polvo", "Mucho sol", "Ruido"]'::jsonb,0,'OSHA winter slip prevention.','OSHA prevención de resbalones en invierno.','https://www.osha.gov/walking-working-surfaces',array['houseman']::text[],'role','easy',array['entrance','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ice_melt','Why not overuse ice melt on the sidewalk?','¿Por qué no usar demasiada sal en la banqueta?','["It damages concrete and plants and gets tracked inside — use the right amount", "It''s free", "It works better", "It warms the floor"]'::jsonb,'["Daña concreto y plantas y se mete al hotel; usa lo justo", "Es gratis", "Funciona mejor", "Calienta el piso"]'::jsonb,0,'MPCA Smart Salting: more salt isn''t more melting.','MPCA: más sal no derrite más.','https://www.pca.state.mn.us/business-with-us/smart-salting-training',array['houseman']::text[],'role','med',array['ice_melt','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','ice_melt','Rock salt (sodium chloride) stops working well below about what temperature?','La sal común deja de funcionar bien debajo de qué temperatura?','["About 60°F", "About 32°F", "About −40°F", "About 15°F"]'::jsonb,'["Unos 60°F", "Unos 32°F", "Unos −40°F", "Unos 15°F"]'::jsonb,3,'MPCA: sodium chloride is less effective below about 15°F.','MPCA: el cloruro de sodio funciona menos debajo de 15°F.','https://www.pca.state.mn.us/business-with-us/smart-salting-training',array['houseman']::text[],'role','hard',array['ice_melt','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','You find a guest''s glass bottle on the pool deck. Why remove it?','Hay una botella de vidrio en la alberca. ¿Por qué quitarla?','["It looks bad only", "It''s not allowed by the brand only", "Broken glass near a pool is a serious injury risk", "No reason"]'::jsonb,'["Solo se ve mal", "Solo regla de marca", "Un vidrio roto en la alberca es riesgo grave", "Por nada"]'::jsonb,2,'Glass is commonly banned around pools.','El vidrio suele prohibirse en albercas.','general hospitality best practice',array['houseman']::text[],'role','med',array['pool','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','pool','The pool water is cloudy. What do you do?','El agua de la alberca está turbia. ¿Qué haces?','["Swim test it", "Report it right away — it may need to close until maintenance checks it", "Add soap", "Ignore"]'::jsonb,'["Probarla nadando", "Reportarlo de inmediato; puede cerrarse hasta que mantenimiento revise", "Echar jabón", "Ignorar"]'::jsonb,1,'MDH: if you can''t see the main drain, the pool must close.','MDH: si no se ve el desagüe, la alberca se cierra.','https://www.health.state.mn.us/communities/environment/pools/',array['houseman']::text[],'role','easy',array['pool','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','deliveries','A guest asks for a rollaway bed. What''s your job?','Un huésped pide cama extra. ¿Qué haces?','["Make the guest pick it up", "Leave it in the hall", "Bring it promptly, made up, and log it", "Tell them no"]'::jsonb,'["Que la recoja él", "Dejarla en el pasillo", "Llevarla pronto, tendida, y registrarla", "Decir que no"]'::jsonb,2,'Logged deliveries are tracked for pickup.','Se registra para recogerla después.','general hospitality best practice',array['houseman']::text[],'role','easy',array['deliveries','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','deliveries','You deliver to a room. How long should you wait at the door?','Entregas algo a un cuarto. ¿Cuánto esperas en la puerta?','["Leave it on the floor without knocking", "Walk in", "Shout", "Knock, announce, step back, and never enter unless invited"]'::jsonb,'["Dejarlo sin tocar", "Entrar", "Gritar", "Tocar, anunciar, retroceder y no entrar si no te invitan"]'::jsonb,3,'Respect privacy and safety.','Respeta privacidad y seguridad.','general hospitality best practice',array['houseman']::text[],'role','med',array['deliveries','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','stock','Why keep floor closets stocked by the end of shift?','¿Por qué dejar surtidos los cuartos de servicio al final del turno?','["It looks nice", "To hide items", "So the next shift and room attendants aren''t waiting", "It''s optional"]'::jsonb,'["Se ve bonito", "Para esconder", "Para que el siguiente turno no espere", "Es opcional"]'::jsonb,2,'Stocking keeps housekeeping moving.','Surtir mantiene el ritmo.','general hospitality best practice',array['houseman']::text[],'role','easy',array['stock','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','chemicals','You need to refill a spray bottle. What''s required?','Rellenas una botella. ¿Qué se requiere?','["Any bottle", "No label needed", "Use the correct chemical and keep the bottle labeled", "A water bottle"]'::jsonb,'["Cualquier botella", "Sin etiqueta", "Usar el químico correcto y que esté etiquetada", "Una de agua"]'::jsonb,2,'OSHA HazCom: secondary containers must be labeled.','HazCom: los envases secundarios se etiquetan.','https://www.osha.gov/hazcom',array['houseman']::text[],'role','med',array['chemicals','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','elevator','An elevator door is not closing right. What do you do?','Una puerta de elevador no cierra bien. ¿Qué haces?','["Kick it", "Report it right away; don''t force it", "Hold it with a cart", "Ignore"]'::jsonb,'["Patearla", "Reportarlo de inmediato; no forzarla", "Detenerla con un carro", "Ignorar"]'::jsonb,1,'Elevators are serviced by licensed techs.','Los elevadores los atienden técnicos.','general hospitality best practice',array['houseman']::text[],'role','easy',array['elevator','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('all','all','odor','A guest reports smoke smell from another room. What do you do?','Un huésped reporta olor a humo de otro cuarto. ¿Qué haces?','["Spray air freshener in the hall", "Ignore", "Knock and yell", "Tell the front desk/manager right away so it can be checked"]'::jsonb,'["Echar aromatizante", "Ignorar", "Tocar y gritar", "Avisar a recepción o gerente de inmediato para revisar"]'::jsonb,3,'Could be smoking or a fire — check fast.','Puede ser alguien fumando o un incendio.','https://www.osha.gov/etools/evacuation-plans-procedures',array['houseman']::text[],'role','med',array['odor','houseman']::text[],null,null,null,null) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','checkout','What is check-out time at our Hampton?','¿A qué hora es la salida (check-out) en nuestro Hampton?','["Noon", "1 p.m.", "10 a.m.", "11 a.m."]'::jsonb,'["Al mediodía", "A la 1 p. m.", "A las 10 a. m.", "A las 11 a. m."]'::jsonb,3,'Hilton lists check-out at 11 a.m. Late check-out depends on availability — ask the desk.','Hilton indica salida a las 11 a. m. La salida tarde depende de disponibilidad; pregunta en recepción.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','checkout','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','parking','A guest asks what self-parking costs per day at our Hampton.','Un huésped pregunta cuánto cuesta el estacionamiento por día en nuestro Hampton.','["$15 per day", "$45 per day, valet only", "Free"]'::jsonb,'["$15 por día", "$45 por día, solo valet", "Gratis"]'::jsonb,0,'Hilton lists on-site self-parking at $15/day with in/out privileges; no valet.','Hilton indica estacionamiento propio a $15 por día, con entrada y salida libre; no hay valet.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['hotel','parking','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','parking','A guest wants covered underground parking at our Hampton. What do you say?','Un huésped quiere estacionamiento techado subterráneo en nuestro Hampton. ¿Qué le dices?','["It''s free for everyone", "We don''t have any parking", "It''s $30 a night and limited — check availability", "Only valet, $50 a night"]'::jsonb,'["Es gratis para todos", "No tenemos estacionamiento", "Cuesta $30 por noche y es limitado; hay que revisar disponibilidad", "Solo valet, $50 por noche"]'::jsonb,2,'Hilton''s page notes $30/night underground parking with limited availability.','La página de Hilton indica estacionamiento subterráneo a $30 por noche con disponibilidad limitada.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['driver','front_desk','gm','night_audit']::text[],'role','hard',array['hotel','parking','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','ev','A guest with an electric car asks about charging at our Hampton.','Un huésped con carro eléctrico pregunta dónde cargar en nuestro Hampton.','["Charging is in the underground ramp", "Plug into the lobby outlet", "There''s no on-site charger — the nearest is about 0.8 miles away", "Chargers are in every parking spot"]'::jsonb,'["Se carga en el estacionamiento subterráneo", "Que conecte en un contacto del lobby", "No hay cargador en el hotel; el más cercano está a unas 0.8 millas", "Hay cargador en cada lugar"]'::jsonb,2,'Hilton lists EV charging ''nearby, 0.80 miles'', not on-site.','Hilton indica carga para eléctricos ''cerca, a 0.80 millas'', no en el hotel.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['hotel','ev','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','pets','A guest wants to bring their dog to our Hampton. What''s the policy?','Un huésped quiere traer a su perro a nuestro Hampton. ¿Cuál es la política?','["Cats only", "No pets at all", "Any pet, any size, free", "Up to 2 dogs, 25 lbs max each, with a non-refundable pet fee"]'::jsonb,'["Solo gatos", "No se aceptan mascotas", "Cualquier mascota, de cualquier tamaño, gratis", "Hasta 2 perros, máximo 25 libras, con cargo no reembolsable"]'::jsonb,3,'Hilton lists dogs up to 25 lbs, max 2 per room, and pets can''t be left unattended.','Hilton indica perros de hasta 25 libras, máximo 2 por cuarto, y no pueden quedarse solos.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','med',array['hotel','pets','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','pets','What''s the pet fee at our Hampton for a 6-night stay?','¿Cuál es el cargo por mascota en nuestro Hampton para 6 noches?','["$125 (non-refundable, 5+ nights)", "$75 per night", "No fee", "$25 total"]'::jsonb,'["$125 (no reembolsable, 5 noches o más)", "$75 por noche", "Sin cargo", "$25 en total"]'::jsonb,0,'Hilton lists $75 for 1–4 nights and $125 for 5+ nights.','Hilton indica $75 por 1 a 4 noches y $125 por 5 noches o más.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','night_audit']::text[],'role','hard',array['hotel','pets','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','pets','A guest at our Hampton wants to leave their dog in the room while they shop at MOA. What''s the rule?','Un huésped de nuestro Hampton quiere dejar a su perro en el cuarto mientras va al MOA. ¿Cuál es la regla?','["Pets may not be left unattended in rooms", "Only for under 4 hours", "Only in suites", "It''s fine with the TV on"]'::jsonb,'["Las mascotas no se pueden dejar solas en el cuarto", "Solo por menos de 4 horas", "Solo en suites", "Está bien con la tele prendida"]'::jsonb,0,'Hilton''s pet policy: pets may not be left unattended in guest rooms.','Política de Hilton: las mascotas no se pueden dejar solas en los cuartos.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','pets','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','shuttle','Does our Hampton''s airport shuttle cost anything?','¿El shuttle al aeropuerto de nuestro Hampton tiene costo?','["No — it''s complimentary", "$10 each way", "$25 round trip", "Only free for Honors members"]'::jsonb,'["No, es gratis", "$10 por trayecto", "$25 ida y vuelta", "Solo es gratis para miembros Honors"]'::jsonb,0,'Hilton lists the airport shuttle as complimentary.','Hilton indica que el shuttle al aeropuerto es gratis.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['hotel','shuttle','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','meetings','A planner asks how big a group our Hampton''s meeting space holds.','Un organizador pregunta para cuántas personas es la sala de juntas de nuestro Hampton.','["We have no meeting space", "Up to 10 people", "Up to about 35 people", "Up to 500 people"]'::jsonb,'["No tenemos salas", "Hasta 10 personas", "Hasta unas 35 personas", "Hasta 500 personas"]'::jsonb,2,'Hilton lists bookable meeting space for up to 35 people.','Hilton indica sala de juntas para hasta 35 personas.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','meetings','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','wifi','Is Wi-Fi free at our Hampton?','¿El Wi-Fi es gratis en nuestro Hampton?','["Only for Honors members", "Yes — free in rooms and the lobby", "$9.95 per day", "Only in the lobby"]'::jsonb,'["Solo para miembros Honors", "Sí, gratis en cuartos y lobby", "$9.95 por día", "Solo en el lobby"]'::jsonb,1,'Hilton lists free in-room and lobby WiFi.','Hilton indica Wi-Fi gratis en cuartos y lobby.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','wifi','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','breakfast','Is breakfast included at our Hampton?','¿El desayuno está incluido en nuestro Hampton?','["Only continental for a fee", "No breakfast", "Yes — free hot breakfast", "Only on weekends"]'::jsonb,'["Solo continental con costo", "No hay desayuno", "Sí, desayuno caliente gratis", "Solo los fines de semana"]'::jsonb,2,'Hilton lists free hot breakfast as a core amenity.','Hilton indica desayuno caliente gratis.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['breakfast','front_desk','gm','night_audit']::text[],'role','easy',array['hotel','breakfast','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','digitalkey','A Hilton Honors guest wants to skip the desk line. What can they use?','Un huésped Hilton Honors quiere evitar la fila. ¿Qué puede usar?','["The shuttle driver''s key", "Nothing, everyone must stop at the desk", "A paper key from housekeeping", "Digital Check-In and Digital Key in the Hilton Honors app"]'::jsonb,'["La llave del chofer", "Nada, todos deben pasar a recepción", "Una llave de papel de limpieza", "El Digital Check-In y la Digital Key en la app Hilton Honors"]'::jsonb,3,'The hotel page lists Digital Check-In and Digital Key as Honors benefits.','La página del hotel indica Digital Check-In y Digital Key como beneficios Honors.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','digitalkey','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','rooms','A family asks if our Hampton has connecting rooms and cribs.','Una familia pregunta si nuestro Hampton tiene cuartos conectados y cunas.','["Yes, both — request them ahead", "No connecting rooms", "Neither", "Cribs only in suites for a fee"]'::jsonb,'["Sí, ambos; hay que pedirlos con anticipación", "No hay cuartos conectados", "Ninguno", "Cunas solo en suites con costo"]'::jsonb,0,'Hilton lists connecting rooms and cribs among amenities.','Hilton incluye cuartos conectados y cunas entre sus servicios.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','rooms','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','location','What''s our Hampton''s main phone number?','¿Cuál es el teléfono principal de nuestro Hampton?','["952-854-7600", "612-726-5555", "952-854-0300", "763-545-8300"]'::jsonb,'["952-854-7600", "612-726-5555", "952-854-0300", "763-545-8300"]'::jsonb,0,'Hilton lists +1 952-854-7600 for the hotel.','Hilton indica +1 952-854-7600 para el hotel.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','night_audit']::text[],'role','easy',array['hotel','location','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Hilton','all','smoking','A guest asks if they can smoke in their room at our Hampton.','Un huésped pregunta si puede fumar en su cuarto en nuestro Hampton.','["No — rooms are non-smoking", "Yes, with the window open", "Only e-cigarettes", "Only on the top floor"]'::jsonb,'["No, los cuartos son de no fumar", "Sí, con la ventana abierta", "Solo cigarros electrónicos", "Solo en el último piso"]'::jsonb,0,'Hilton lists non-smoking rooms.','Hilton indica cuartos de no fumar.','https://www.hilton.com/en/hotels/mspamhx-hampton-suites-minneapolis-st-paul-arpt-mall-of-america/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','smoking','mspam']::text[],'MSPAM',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','checkin','What are check-in and check-out times at our SpringHill?','¿A qué hora son la entrada y la salida en nuestro SpringHill?','["Check-in 4 p.m., check-out 10 a.m.", "Check-in noon, check-out 3 p.m.", "Check-in 3 p.m., check-out noon", "Check-in 1 p.m., check-out 11 a.m."]'::jsonb,'["Entrada a las 4 p. m., salida a las 10 a. m.", "Entrada al mediodía, salida a las 3 p. m.", "Entrada a las 3 p. m., salida al mediodía", "Entrada a la 1 p. m., salida a las 11 a. m."]'::jsonb,2,'Marriott lists check-in 3:00 pm and check-out 12:00 pm.','Marriott indica entrada a las 3:00 p. m. y salida a las 12:00 p. m.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','checkin','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','age','What''s the minimum age to check in at our SpringHill?','¿Cuál es la edad mínima para registrarse en nuestro SpringHill?','["18", "25", "16", "21"]'::jsonb,'["18", "25", "16", "21"]'::jsonb,3,'Marriott lists minimum check-in age 21.','Marriott indica edad mínima de 21 años.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['bartender','front_desk','gm','night_audit']::text[],'role','med',array['hotel','age','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','breakfast','On a Tuesday, what are breakfast hours at our SpringHill?','Un martes, ¿cuál es el horario del desayuno en nuestro SpringHill?','["8–11 a.m.", "6–9 a.m.", "7–10 a.m.", "5–8 a.m."]'::jsonb,'["De 8 a 11 a. m.", "De 6 a 9 a. m.", "De 7 a 10 a. m.", "De 5 a 8 a. m."]'::jsonb,1,'Marriott lists breakfast Mon–Fri 6:00–9:00 a.m., Sat–Sun 7:00–10:00 a.m.','Marriott indica desayuno lunes a viernes de 6:00 a 9:00 a. m., sábado y domingo de 7:00 a 10:00 a. m.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['breakfast','front_desk','gm','night_audit']::text[],'role','easy',array['hotel','breakfast','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','breakfast','On Sunday, until what time is breakfast served at our SpringHill?','El domingo, ¿hasta qué hora se sirve el desayuno en nuestro SpringHill?','["8:30 a.m.", "9 a.m.", "10 a.m.", "Noon"]'::jsonb,'["Hasta las 8:30 a. m.", "Hasta las 9 a. m.", "Hasta las 10 a. m.", "Hasta el mediodía"]'::jsonb,2,'Weekend breakfast is 7:00–10:00 a.m.','El desayuno del fin de semana es de 7:00 a 10:00 a. m.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['breakfast','front_desk','gm','night_audit']::text[],'role','med',array['hotel','breakfast','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','pets','A guest asks to bring a pet dog to our SpringHill. What''s the policy?','Un huésped quiere traer a su perro a nuestro SpringHill. ¿Cuál es la política?','["Dogs under 25 lbs for $75", "Pets aren''t allowed — service animals are welcome with no fee", "Any pet for $50 a night", "Cats only"]'::jsonb,'["Perros de menos de 25 libras por $75", "No se aceptan mascotas; los animales de servicio son bienvenidos sin cargo", "Cualquier mascota por $50 la noche", "Solo gatos"]'::jsonb,1,'Marriott lists ''Pets Not Allowed'' and service animals welcome without a fee or documentation.','Marriott indica que no se aceptan mascotas y que los animales de servicio son bienvenidos sin cargo ni documentos.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','pets','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','parking','A SpringHill guest wants to leave their car with us while they fly. What do you tell them?','Un huésped de nuestro SpringHill quiere dejar su carro mientras viaja. ¿Qué le dices?','["They need to book the Park & Fly package", "Leave it on Metro Drive", "We don''t allow any parking", "It''s free to leave it any time"]'::jsonb,'["Debe reservar el paquete Park & Fly", "Que lo deje en Metro Drive", "No permitimos estacionarse", "Se puede dejar gratis cuando quiera"]'::jsonb,0,'Marriott notes a Park & Fly package rate must be booked to leave a vehicle; regular parking is $15/day, 1 vehicle max.','Marriott indica que para dejar el carro hay que reservar Park & Fly; el estacionamiento normal es $15 por día, 1 vehículo máximo.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','med',array['hotel','parking','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','parking','What does daily self-parking cost at our SpringHill?','¿Cuánto cuesta el estacionamiento diario en nuestro SpringHill?','["$15 per day", "Free", "$40 per day, valet only"]'::jsonb,'["$15 por día", "Gratis", "$40 por día, solo valet"]'::jsonb,0,'Marriott lists on-site parking at $15 daily.','Marriott indica estacionamiento a $15 por día.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['driver','front_desk','gm','night_audit']::text[],'role','easy',array['hotel','parking','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','ev','An EV driver asks about charging at our SpringHill.','Un conductor de eléctrico pregunta por carga en nuestro SpringHill.','["Chargers are in the underground lot", "We don''t have EV charging stations on-site", "Charging is free in front", "Every spot has a charger"]'::jsonb,'["Hay cargadores en el subterráneo", "No tenemos estaciones de carga en el hotel", "La carga es gratis enfrente", "Cada lugar tiene cargador"]'::jsonb,1,'Marriott''s FAQ says the hotel does not have EV charging stations.','El FAQ de Marriott dice que el hotel no tiene estaciones de carga.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','ev','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','rooms','What''s in every suite at our SpringHill?','¿Qué hay en cada suite de nuestro SpringHill?','["Microwave, refrigerator, sofa bed and wet bar", "A washer and dryer", "A hot tub", "A full kitchen with stove"]'::jsonb,'["Microondas, refrigerador, sofá cama y barra con tarja", "Lavadora y secadora", "Jacuzzi", "Cocina completa con estufa"]'::jsonb,0,'Marriott says every suite has a microwave, refrigerator, sofa bed and wet bar.','Marriott dice que cada suite tiene microondas, refrigerador, sofá cama y barra con tarja.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','rooms','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','housekeeping','How often is housekeeping provided at our SpringHill?','¿Cada cuándo se da servicio de limpieza en nuestro SpringHill?','["Every day at 8 a.m.", "Every other day", "Twice a day", "Only at checkout"]'::jsonb,'["Todos los días a las 8 a. m.", "Cada tercer día", "Dos veces al día", "Solo a la salida"]'::jsonb,1,'Marriott lists housekeeping ''Every Other Day''. Guests can still request service.','Marriott indica limpieza ''cada tercer día''. El huésped puede pedir servicio.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','med',array['hotel','housekeeping','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','fitness','When can guests use the fitness center at our SpringHill?','¿Cuándo pueden usar el gimnasio en nuestro SpringHill?','["6 a.m.–10 p.m.", "24/7", "Only during breakfast", "Weekends only"]'::jsonb,'["De 6 a. m. a 10 p. m.", "Las 24 horas, los 7 días", "Solo en el desayuno", "Solo los fines de semana"]'::jsonb,1,'Marriott lists a 24-hour fitness center.','Marriott indica gimnasio abierto las 24 horas.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','fitness','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','bar','What does the SpringHill Lounge serve?','¿Qué sirve el SpringHill Lounge?','["Only coffee", "Full steakhouse dinner", "Nothing — it''s a lobby", "Wines, local craft beers, sodas and pizza"]'::jsonb,'["Solo café", "Cena completa de cortes", "Nada, es un lobby", "Vinos, cervezas artesanales locales, refrescos y pizza"]'::jsonb,3,'Marriott describes wines, local craft beers, sodas and pizza at the lounge.','Marriott describe vinos, cervezas artesanales locales, refrescos y pizza en el lounge.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['bartender','front_desk','gm','night_audit']::text[],'role','easy',array['hotel','bar','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','accessibility','A guest who is deaf asks what we have for them at our SpringHill.','Un huésped sordo pregunta qué tenemos para él en nuestro SpringHill.','["Hearing-accessible rooms/kits with flashing door knockers and closed-caption TV", "Nothing special", "A sign-language interpreter 24/7", "Only a large-print menu"]'::jsonb,'["Cuartos o kits para personas con discapacidad auditiva, con aviso luminoso en la puerta y TV con subtítulos", "Nada especial", "Un intérprete de señas 24/7", "Solo un menú en letra grande"]'::jsonb,0,'Marriott lists hearing accessible rooms/kits, flashing door knockers, closed-caption TV and TTY.','Marriott indica cuartos/kits auditivos, aviso luminoso, TV con subtítulos y TTY.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','med',array['hotel','accessibility','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('Marriott','all','accessibility','A wheelchair user asks about the shower at our SpringHill.','Un usuario de silla de ruedas pregunta por la regadera en nuestro SpringHill.','["We have no accessible rooms", "Only on the top floor", "All tubs only", "We have mobility-accessible rooms with roll-in showers"]'::jsonb,'["No hay cuartos accesibles", "Solo en el último piso", "Solo tinas", "Tenemos cuartos accesibles con regadera sin escalón (roll-in)"]'::jsonb,3,'Marriott lists mobility-accessible rooms, roll-in showers, grab rails and a tub seat.','Marriott indica cuartos accesibles, regaderas roll-in, barras y asiento para tina.','https://www.marriott.com/en-us/hotels/mspms-springhill-suites-minneapolis-st-paul-airport-mall-of-america/overview/',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','med',array['hotel','accessibility','mspms']::text[],'MSPMS',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
