insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','parking','What does parking cost at our Holiday Inn Express?','¿Cuánto cuesta el estacionamiento en nuestro Holiday Inn Express?','["$40 per night valet", "$10 per day", "Free", "$25 per day"]'::jsonb,'["$40 por noche con valet", "$10 por día", "Gratis", "$25 por día"]'::jsonb,1,'IHG lists self-parking at 10 USD per day with in/out privileges.','IHG indica estacionamiento a 10 USD por día, con entrada y salida libre.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','easy',array['hotel','parking','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','parking','A youth hockey team arrives on a bus with a trailer. Where do they park at our Holiday Inn Express?','Un equipo de hockey llega en autobús con remolque. ¿Dónde se estaciona en nuestro Holiday Inn Express?','["On Golden Hills Drive", "At West End", "In the rear lot — oversized, bus, trailer and RV parking is available", "We can''t take buses"]'::jsonb,'["En Golden Hills Drive", "En West End", "En el lote trasero; hay lugar para vehículos grandes, autobús, remolque y RV", "No aceptamos autobuses"]'::jsonb,2,'IHG: oversized and truck parking in the rear lot; buses, trucks, trailers and RVs allowed.','IHG: lugares para vehículos grandes en el lote trasero; se permiten autobuses, camiones, remolques y RV.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','parking','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','ev','Does our Holiday Inn Express have EV charging?','¿Nuestro Holiday Inn Express tiene carga para eléctricos?','["Only in winter", "Yes — EV chargers are on-site", "Only for staff", "No, the nearest is downtown"]'::jsonb,'["Solo en invierno", "Sí, hay cargadores en el hotel", "Solo para empleados", "No, el más cercano está en el centro"]'::jsonb,1,'IHG lists EV chargers among the hotel''s amenities.','IHG incluye cargadores para eléctricos entre los servicios.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','easy',array['hotel','ev','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','pets','A guest wants to bring their cat to our Holiday Inn Express. What do you say?','Un huésped quiere traer a su gato a nuestro Holiday Inn Express. ¿Qué le dices?','["Cats are fine for $50", "Pets stay free", "Pets aren''t allowed (service animals are always welcome)", "Only small dogs"]'::jsonb,'["Gatos sí, por $50", "Las mascotas no pagan", "No se aceptan mascotas (los animales de servicio siempre son bienvenidos)", "Solo perros chicos"]'::jsonb,2,'IHG''s FAQ says pets are not allowed. Under the ADA, service animals are still admitted.','El FAQ de IHG dice que no se aceptan mascotas. Por la ADA, los animales de servicio sí pueden entrar.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','pets','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','housekeeping','How often is housekeeping at our Holiday Inn Express?','¿Cada cuándo hay limpieza en nuestro Holiday Inn Express?','["Only at checkout", "Every third day", "Daily", "Weekly"]'::jsonb,'["Solo a la salida", "Cada tres días", "Diario", "Semanal"]'::jsonb,2,'IHG lists daily housekeeping.','IHG indica limpieza diaria.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','med',array['hotel','housekeeping','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','rooms','What does every room at our Holiday Inn Express include?','¿Qué incluye cada cuarto de nuestro Holiday Inn Express?','["A hot tub", "A full kitchen", "A microwave and refrigerator", "A washer and dryer"]'::jsonb,'["Jacuzzi", "Cocina completa", "Microondas y refrigerador", "Lavadora y secadora"]'::jsonb,2,'IHG says every guest room includes a microwave and refrigerator as standard.','IHG dice que cada cuarto incluye microondas y refrigerador.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','rooms','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','rooms','A family of five asks what room type fits best at our Holiday Inn Express.','Una familia de cinco pregunta qué tipo de cuarto le conviene en nuestro Holiday Inn Express.','["A single king", "The meeting room", "We only have one room type", "A one-bedroom suite with a sofa bed"]'::jsonb,'["Un king sencillo", "La sala de juntas", "Solo hay un tipo de cuarto", "Una suite de una recámara con sofá cama"]'::jsonb,3,'IHG lists one-bedroom suites with sofa beds, microwave and refrigerator.','IHG indica suites de una recámara con sofá cama, microondas y refrigerador.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','rooms','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','coffee','A guest wants coffee at 2 a.m. at our Holiday Inn Express. What do you say?','Un huésped quiere café a las 2 a. m. en nuestro Holiday Inn Express. ¿Qué le dices?','["Go to the gas station", "The bean-to-cup machine in the lobby runs 24/7", "Coffee is only at breakfast", "We don''t serve coffee"]'::jsonb,'["Que vaya a la gasolinera", "La máquina de café en grano del lobby funciona 24/7", "Solo hay café en el desayuno", "No damos café"]'::jsonb,1,'IHG says the bean-to-cup coffee machine is available 24/7 in the lobby.','IHG dice que la máquina de café está disponible 24/7 en el lobby.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','hk_supervisor','houseman','night_audit','room_attendant']::text[],'role','easy',array['hotel','coffee','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','dining','A guest asks if our Holiday Inn Express has a restaurant.','Un huésped pregunta si nuestro Holiday Inn Express tiene restaurante.','["Yes, a steakhouse", "Yes, room service 24/7", "No on-site restaurant — West End restaurants are about 0.7 miles away", "Only a bar"]'::jsonb,'["Sí, un restaurante de cortes", "Sí, servicio a cuartos 24/7", "No hay restaurante; los de West End están a unas 0.7 millas", "Solo un bar"]'::jsonb,2,'IHG: no on-site restaurant; The Shops at West End is listed 0.7 miles away.','IHG: no hay restaurante; The Shops at West End está a 0.7 millas.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','easy',array['hotel','dining','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
insert into public.qotd_questions(brand,role_group,topic,question_en,question_es,options_en,options_es,correct_idx,explain_en,explain_es,source_url,roles,kind,difficulty,topics,hotel_id,season_start,season_end,review_by) values ('IHG','all','airport','About how far is MSP airport from our Holiday Inn Express?','¿Más o menos a qué distancia está el aeropuerto MSP de nuestro Holiday Inn Express?','["Under 2 miles", "Next door", "Over 100 miles", "Roughly 20 miles"]'::jsonb,'["A menos de 2 millas", "Al lado", "A más de 100 millas", "Como a 20 millas"]'::jsonb,3,'IHG''s FAQ lists MSP at about 20 miles. Suggest rideshare or taxi — we have no shuttle.','El FAQ de IHG indica unas 20 millas al MSP. Sugiere rideshare o taxi; no hay shuttle.','https://www.ihg.com/holidayinnexpress/hotels/us/en/minneapolis/mspwe/hoteldetail',array['front_desk','gm','night_audit']::text[],'role','med',array['hotel','airport','mspwe']::text[],'MSPWE',null,null,'2027-04-26'::date) on conflict (brand,role_group,question_en) do nothing;
